CREATE OR REPLACE FUNCTION public.sgp_aluminio_pendiente_resolver(p_token text, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u text;
BEGIN
   PERFORM 1 FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
   IF EXISTS(SELECT 1 FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id AND contrato_pdt='V2')
   THEN RAISE EXCEPTION 'PDT_V2_USAR_RPC_DEDICADA'; END IF;

 u:=sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR','LIDER MECANIZADO','LIDER','LIDER LINEA']);
 update sgp_aluminio_pendientes set estado='RESUELTO',usuario_cierre=u,fecha_cierre=now() where id_pendiente=p_id;
end $function$

CREATE OR REPLACE FUNCTION public.sgp_aluminio_pendiente_estado(p_token text, p_id uuid, p_estado text, p_observacion text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u text; old text; ns text:=upper(trim(p_estado)); ve text;
BEGIN
   PERFORM 1 FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
   IF EXISTS(SELECT 1 FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id AND contrato_pdt='V2')
   THEN RAISE EXCEPTION 'PDT_V2_USAR_RPC_DEDICADA'; END IF;

 u:=public.sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR','LIDER MECANIZADO','LIDER']);
 if ns not in ('PENDIENTE','REPO_OK','CORTE','MECANIZADO','PROCESADO','PICKING') then raise exception 'Estado no válido'; end if;
 select estado_repo,coalesce(validacion_estado,'POR_VALIDAR') into old,ve
 from public.sgp_aluminio_pendientes where id_pendiente=p_id and estado='PENDIENTE' for update;
 if old is null then raise exception 'Pendiente no encontrado'; end if;
 if ns<>'PENDIENTE' and ve<>'VALIDADO' then
   raise exception 'PDT POR VALIDAR: debe ser validado antes de avanzar a %',replace(ns,'_',' ');
 end if;
 update public.sgp_aluminio_pendientes
 set estado_repo=ns,usuario_estado=u,fecha_estado=now(),
     fecha_repo_ok=case when ns='REPO_OK' then coalesce(fecha_repo_ok,now()) else fecha_repo_ok end
 where id_pendiente=p_id;
 insert into public.sgp_aluminio_pendientes_historial(
   id_pendiente,estado_anterior,estado_nuevo,usuario,observacion,tipo_evento,datos_anteriores,datos_nuevos
 ) values(
   p_id,old,ns,u,p_observacion,'ESTADO_REPO',
   jsonb_build_object('estado_repo',old),jsonb_build_object('estado_repo',ns)
 );
 return jsonb_build_object('ok',true,'estado',ns);
end $function$

CREATE OR REPLACE FUNCTION public.sgp_picking_validar_recepcion(p_token text, p_id_entrega uuid, p_faltantes jsonb DEFAULT '[]'::jsonb, p_diferencias jsonb DEFAULT '[]'::jsonb, p_observacion text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u text; e record; f jsonb; d jsonb; v_diff boolean:=false; v_key text; v_shared boolean:=false; v_principal text; v_pending_res text; v_finish text;
begin
 u:=public.sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR','PICKING','SUPERVISOR DE PICKING','LIDER LINEA','LIDER']);
 select pe.*,mp.reserva into e from public.sgp_picking_entregas pe join public.sgp_mecanizado_programacion mp on mp.id_programacion=pe.id_programacion where pe.id_entrega=p_id_entrega for update;
 if e.id_entrega is null then raise exception 'Entrega no encontrada'; end if;
 if e.estado<>'PENDIENTE_VALIDACION' then raise exception 'La entrega ya fue auditada'; end if;
 select v.key_produccion,v.reserva_principal,bool_or(v.es_reserva_compartida)
 into v_key,v_principal,v_shared
 from public.sgp_produccion_reservas_v v
 where v.produccion=e.produccion and v.reserva_principal=e.reserva
 group by v.key_produccion,v.reserva_principal
 order by max(v.semana_produccion) desc limit 1;
 v_principal:=coalesce(v_principal,e.reserva);v_shared:=coalesce(v_shared,false);
 for f in select value from jsonb_array_elements(coalesce(p_faltantes,'[]')) loop
  if coalesce((f->>'ventanas_afectadas')::int,0)<1 then raise exception 'Indique las ventanas afectadas de cada faltante'; end if;
  update public.sgp_picking_faltantes set ventanas_afectadas=(f->>'ventanas_afectadas')::int,auditado=true,usuario_auditoria=u,fecha_auditoria=now()
   where id_faltante=(f->>'id_faltante')::uuid and id_entrega=p_id_entrega;
  update public.sgp_aluminio_pendientes set ventanas_afectadas=(f->>'ventanas_afectadas')::int,auditado=true
   where produccion=e.produccion and id_pieza is not distinct from nullif(f->>'id_pieza','') and estado='PENDIENTE'
     and (reserva=e.reserva or reserva=(select pf.reserva_pendiente from public.sgp_picking_faltantes pf where pf.id_faltante=(f->>'id_faltante')::uuid));
 end loop;
 for d in select value from jsonb_array_elements(coalesce(p_diferencias,'[]')) loop
  v_diff:=true;
  v_pending_res:=coalesce(nullif(trim(d->>'reserva'),''),e.reserva);
  if v_key is not null and not exists(select 1 from public.sgp_produccion_reservas_v v where v.key_produccion=v_key and v.reserva=v_pending_res) then
    raise exception 'Seleccione una reserva válida para la diferencia de la orden con reserva compartida';
  end if;
  select v.acabado_reserva into v_finish from public.sgp_produccion_reservas_v v where v.key_produccion=v_key and v.reserva=v_pending_res limit 1;
  v_finish:=coalesce(nullif(trim(d->>'acabado'),''),v_finish);
  insert into public.sgp_picking_auditoria_diferencias(id_entrega,id_pieza,perfil,marca,fabricacion,longitud,cantidad,ventanas_afectadas,observacion,usuario_auditoria,reserva_pendiente,acabado_pendiente)
  values(p_id_entrega,nullif(d->>'id_pieza',''),d->>'perfil',nullif(d->>'marca',''),nullif(d->>'fabricacion',''),nullif(d->>'longitud','')::numeric,
         greatest(coalesce((d->>'cantidad')::numeric,1),1),greatest(coalesce((d->>'ventanas_afectadas')::int,1),1),nullif(d->>'observacion',''),u,v_pending_res,v_finish);
  insert into public.sgp_aluminio_pendientes(
    reserva,reserva_principal,key_produccion,es_reserva_compartida,acabado_pendiente,
    produccion,perfil,cantidad,longitud,origen,causa,observacion,estado,usuario_reporte,id_pieza,marca,fabricacion,estado_repo,ventanas_afectadas,auditado
  ) values(
    v_pending_res,v_principal,v_key,v_shared,v_finish,e.produccion,d->>'perfil',
    greatest(coalesce((d->>'cantidad')::numeric,1),1),nullif(d->>'longitud','')::numeric,
    'PICKING_AUDITORIA','DIFERENCIA_AUDITORIA',nullif(d->>'observacion',''),'PENDIENTE',u,
    nullif(d->>'id_pieza',''),nullif(d->>'marca',''),nullif(d->>'fabricacion',''),'PENDIENTE',
    greatest(coalesce((d->>'ventanas_afectadas')::int,1),1),true
  );
 end loop;
 update public.sgp_picking_entregas set estado=case when v_diff then 'AUDITADA_DIFERENCIA' else 'VALIDADA' end,usuario_validacion=u,fecha_validacion=now(),
  observacion_validacion=nullif(trim(coalesce(p_observacion,'')),'') where id_entrega=p_id_entrega;
 return jsonb_build_object('ok',true,'estado',case when v_diff then 'AUDITADA_DIFERENCIA' else 'VALIDADA' end);
end $function$

CREATE OR REPLACE FUNCTION sgp_pdt_compat_91.sgp_picking_entrega_orden(p_token text, p_id_programacion uuid, p_produccion text, p_completa boolean, p_observacion text DEFAULT NULL::text, p_faltantes jsonb DEFAULT '[]'::jsonb, p_fecha_entrega date DEFAULT NULL::date, p_turno text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u text; eid uuid; f jsonb; v_reserva text; v_fecha date; v_turno text; v_key text; v_shared boolean:=false;
        v_pending_res text; v_finish text; v_principal text;
begin
 u:=public.sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR','LIDER MECANIZADO','LIDER','PATINADOR','PICKING','SUPERVISOR DE PICKING','LIDER LINEA']);
 select reserva into v_reserva from public.sgp_mecanizado_programacion where id_programacion=p_id_programacion and estado<>'CANCELADA';
 if v_reserva is null then raise exception 'Programación no encontrada'; end if;
 select v.key_produccion,v.reserva_principal,bool_or(v.es_reserva_compartida)
 into v_key,v_principal,v_shared
 from public.sgp_produccion_reservas_v v
 where v.produccion=p_produccion and v.reserva_principal=v_reserva
 group by v.key_produccion,v.reserva_principal
 order by max(v.semana_produccion) desc
 limit 1;
 v_principal:=coalesce(v_principal,v_reserva); v_shared:=coalesce(v_shared,false);
 v_fecha:=coalesce(p_fecha_entrega,(now() at time zone 'America/Bogota')::date);
 v_turno:=upper(trim(coalesce(p_turno,'')));
 if v_turno not in ('TURNO 1','TURNO 2') then raise exception 'Debe seleccionar el turno de entrega'; end if;
 if not p_completa and jsonb_array_length(coalesce(p_faltantes,'[]'))=0 then raise exception 'Debe registrar al menos un faltante'; end if;
 insert into public.sgp_picking_entregas(id_programacion,produccion,completa,estado,observacion,usuario_entrega,fecha_entrega,fecha_operativa,turno_entrega)
 values(p_id_programacion,p_produccion,p_completa,'PENDIENTE_VALIDACION',nullif(trim(coalesce(p_observacion,'')),''),u,now(),v_fecha,v_turno)
 returning id_entrega into eid;
 if not p_completa then
  for f in select value from jsonb_array_elements(p_faltantes) loop
   v_pending_res:=coalesce(nullif(trim(f->>'reserva'),''),v_reserva);
   if v_key is not null and not exists(select 1 from public.sgp_produccion_reservas_v v where v.key_produccion=v_key and v.reserva=v_pending_res) then
     raise exception 'Seleccione una reserva válida para el faltante de la orden con reserva compartida';
   end if;
   select v.acabado_reserva into v_finish from public.sgp_produccion_reservas_v v where v.key_produccion=v_key and v.reserva=v_pending_res limit 1;
   v_finish:=coalesce(nullif(trim(f->>'acabado'),''),v_finish);
   insert into public.sgp_picking_faltantes(id_entrega,id_pieza,produccion,perfil,marca,fabricacion,longitud,cantidad,observacion,nc,reserva_pendiente,acabado_pendiente)
   values(eid,f->>'id_pieza',p_produccion,f->>'perfil',nullif(f->>'marca',''),nullif(f->>'fabricacion',''),nullif(f->>'longitud','')::numeric,
          greatest(coalesce((f->>'cantidad')::numeric,1),1),nullif(f->>'observacion',''),nullif(f->>'nc',''),v_pending_res,v_finish);
   insert into public.sgp_aluminio_pendientes(
     reserva,reserva_principal,key_produccion,es_reserva_compartida,acabado_pendiente,
     produccion,perfil,cantidad,longitud,origen,causa,observacion,estado,usuario_reporte,id_pieza,marca,fabricacion,nc,estado_repo
   ) values(
     v_pending_res,v_principal,v_key,v_shared,v_finish,p_produccion,f->>'perfil',
     greatest(coalesce((f->>'cantidad')::numeric,1),1),nullif(f->>'longitud','')::numeric,
     'PICKING','FALTANTE_ENTREGA',nullif(f->>'observacion',''),'PENDIENTE',u,
     nullif(f->>'id_pieza',''),nullif(f->>'marca',''),nullif(f->>'fabricacion',''),nullif(f->>'nc',''),'PENDIENTE'
   );
  end loop;
 end if;
 return jsonb_build_object('ok',true,'id_entrega',eid,'estado','PENDIENTE_VALIDACION','fecha_entrega',v_fecha,'turno',v_turno);
end $function$

CREATE OR REPLACE FUNCTION public.sgp_aluminio_pendiente_editar(p_token text, p_id uuid, p_nc text DEFAULT NULL::text, p_fabricacion text DEFAULT NULL::text, p_longitud numeric DEFAULT NULL::numeric, p_reserva text DEFAULT NULL::text, p_acabado text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 u text; v public.sgp_aluminio_pendientes%rowtype;
 v_nc text:=nullif(trim(coalesce(p_nc,'')),'');
 v_fabricacion text:=nullif(trim(coalesce(p_fabricacion,'')),'');
 v_reserva text; v_acabado text; v_shared boolean;
 v_prod_num text; v_has_source boolean:=false; v_exact boolean:=false;
 old_data jsonb; new_data jsonb;
BEGIN
   PERFORM 1 FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
   IF EXISTS(SELECT 1 FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id AND contrato_pdt='V2')
   THEN RAISE EXCEPTION 'PDT_V2_USAR_RPC_DEDICADA'; END IF;

 u:=public.sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','PATINADOR']);
 select * into v from public.sgp_aluminio_pendientes where id_pendiente=p_id for update;
 if not found then raise exception 'Pendiente no encontrado'; end if;
 if v.estado<>'PENDIENTE' or coalesce(v.estado_repo,'PENDIENTE')='PICKING' then raise exception 'El pendiente ya no está activo'; end if;
 if coalesce(v.validacion_estado,'POR_VALIDAR')='VALIDADO' then raise exception 'El pendiente ya fue validado y no puede ser modificado por Patinador'; end if;
 if v_fabricacion is null then raise exception 'Debes seleccionar una fabricación'; end if;
 if p_longitud is null or p_longitud<=0 then raise exception 'Debes seleccionar una longitud válida'; end if;

 v_shared:=coalesce(v.es_reserva_compartida,false);
 if v.key_produccion is not null then v_shared:=coalesce(public.sgp_es_reserva_compartida(v.key_produccion),v_shared); end if;
 v_reserva:=coalesce(nullif(trim(coalesce(p_reserva,'')),''),v.reserva);
 v_acabado:=coalesce(nullif(trim(coalesce(p_acabado,'')),''),v.acabado_pendiente);

 if not v_shared then
   if nullif(trim(coalesce(p_acabado,'')),'') is not null
      and nullif(trim(coalesce(p_acabado,'')),'') is distinct from nullif(trim(coalesce(v.acabado_pendiente,'')),'') then
     raise exception 'El Patinador solo puede modificar el acabado cuando la orden es RESERVA COMPARTIDA';
   end if;
   v_reserva:=v.reserva; v_acabado:=v.acabado_pendiente;
 elsif v.key_produccion is not null then
   if not exists(
     select 1 from public.sgp_produccion_reservas_v r
     where r.key_produccion=v.key_produccion and r.reserva=v_reserva
       and (r.acabado_reserva is null or upper(trim(r.acabado_reserva))=upper(trim(coalesce(v_acabado,''))))
   ) then raise exception 'La combinación reserva/acabado no pertenece a esta producción compartida'; end if;
 end if;

 v_prod_num:=nullif(substring(coalesce(v.produccion,'') from '^[[:space:]]*([0-9]+)'),'');
 select exists(select 1 from public.sgp_aluminio a where a.activo='SI' and a.tipo_pieza='PANEL'
   and trim(coalesce(a.codigo_sap,''))=trim(coalesce(v.perfil,''))
   and ((v.key_produccion is not null and a.key_produccion=v.key_produccion) or a.produccion=v.produccion))
 into v_exact;
 select exists(select 1 from public.sgp_aluminio a where a.activo='SI' and a.tipo_pieza='PANEL'
   and trim(coalesce(a.codigo_sap,''))=trim(coalesce(v.perfil,''))
   and ((v.key_produccion is not null and a.key_produccion=v.key_produccion) or a.produccion=v.produccion
        or (not v_exact and v_prod_num is not null and substring(coalesce(a.produccion,'') from '^[[:space:]]*([0-9]+)')=v_prod_num)))
 into v_has_source;
 if v_has_source and not exists(
   select 1 from public.sgp_aluminio a
   where a.activo='SI' and a.tipo_pieza='PANEL'
     and trim(coalesce(a.codigo_sap,''))=trim(coalesce(v.perfil,''))
     and lower(trim(coalesce(a.fabricacion,'')))=lower(trim(v_fabricacion))
     and a.longitud=p_longitud
     and (not v_shared or v_acabado is null or upper(trim(coalesce(a.acabado,'')))=upper(trim(v_acabado)))
     and ((v.key_produccion is not null and a.key_produccion=v.key_produccion) or a.produccion=v.produccion
          or (not v_exact and v_prod_num is not null and substring(coalesce(a.produccion,'') from '^[[:space:]]*([0-9]+)')=v_prod_num))
 ) then raise exception 'La fabricación/longitud seleccionada no corresponde a las piezas registradas en esta orden'; end if;

 old_data:=jsonb_build_object('nc',v.nc,'fabricacion',v.fabricacion,'longitud',v.longitud,'reserva',v.reserva,'acabado',v.acabado_pendiente);
 update public.sgp_aluminio_pendientes
 set nc=v_nc,fabricacion=v_fabricacion,longitud=p_longitud,reserva=v_reserva,acabado_pendiente=v_acabado
 where id_pendiente=p_id;
 new_data:=jsonb_build_object('nc',v_nc,'fabricacion',v_fabricacion,'longitud',p_longitud,'reserva',v_reserva,'acabado',v_acabado);
 insert into public.sgp_aluminio_pendientes_historial(id_pendiente,estado_anterior,estado_nuevo,usuario,observacion,tipo_evento,datos_anteriores,datos_nuevos)
 values(p_id,v.estado_repo,v.estado_repo,u,'Edición previa a validación por Patinador','EDICION_PDT',old_data,new_data);
 return jsonb_build_object('ok',true,'id_pendiente',p_id,'validacion_estado','POR_VALIDAR');
end $function$

CREATE OR REPLACE FUNCTION public.sgp_aluminio_pendiente_reserva_solucion(p_token text, p_id uuid, p_reserva_solucion text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  u text;
  v public.sgp_aluminio_pendientes%rowtype;
  v_sol text:=nullif(trim(coalesce(p_reserva_solucion,'')),'');
  v_nc_sol text;
BEGIN
   PERFORM 1 FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
   IF EXISTS(SELECT 1 FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id AND contrato_pdt='V2')
   THEN RAISE EXCEPTION 'PDT_V2_USAR_RPC_DEDICADA'; END IF;

  u:=public.sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR']);
  select * into v from public.sgp_aluminio_pendientes where id_pendiente=p_id for update;
  if not found then raise exception 'Pendiente no encontrado'; end if;
  if v.estado<>'PENDIENTE' or coalesce(v.estado_repo,'PENDIENTE')='PICKING' then raise exception 'El pendiente ya no está activo'; end if;
  if coalesce(v.validacion_estado,'POR_VALIDAR')='VALIDADO' then raise exception 'El pendiente ya fue validado'; end if;
  if nullif(trim(coalesce(v.nc,'')),'') is not null then
    select nullif(trim(n.reserva_solucion),'') into v_nc_sol
    from public.sgp_nc_aluminio n
    where n.activo=true and (n.consecutivo=v.nc or n.cod_nc=v.nc)
    order by n.fecha_actualizacion desc nulls last limit 1;
    if v_nc_sol is not null then
      raise exception 'La reserva solución proviene de la NC enlazada y no se modifica desde Pendientes';
    end if;
    raise exception 'El pendiente tiene NC asociada; la reserva solución debe gestionarse desde la NC';
  end if;
  insert into public.sgp_aluminio_pendientes_historial(
    id_pendiente,estado_anterior,estado_nuevo,usuario,observacion,tipo_evento,datos_anteriores,datos_nuevos
  ) values(
    p_id,v.estado_repo,v.estado_repo,u,'Asignación de reserva solución manual','RESERVA_SOLUCION',
    jsonb_build_object('reserva_solucion_manual',v.reserva_solucion_manual),
    jsonb_build_object('reserva_solucion_manual',v_sol)
  );
  update public.sgp_aluminio_pendientes set reserva_solucion_manual=v_sol where id_pendiente=p_id;
  return jsonb_build_object('ok',true,'reserva_solucion',v_sol,'origen','MANUAL');
end $function$

CREATE OR REPLACE FUNCTION public.sgp_aluminio_pendiente_validar(p_token text, p_id uuid, p_fabricacion text, p_longitud numeric, p_reserva text DEFAULT NULL::text, p_acabado text DEFAULT NULL::text, p_observacion text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 u text; v public.sgp_aluminio_pendientes%rowtype;
 v_fab text:=nullif(trim(coalesce(p_fabricacion,'')),'');
 v_res text; v_acab text:=nullif(trim(coalesce(p_acabado,'')),'');
 v_prod_num text; v_has_source boolean:=false; v_exact boolean:=false;
 old_data jsonb; new_data jsonb;
BEGIN
   PERFORM 1 FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
   IF EXISTS(SELECT 1 FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id AND contrato_pdt='V2')
   THEN RAISE EXCEPTION 'PDT_V2_USAR_RPC_DEDICADA'; END IF;

 u:=public.sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR','LIDER LINEA','SUPERVISOR DE PICKING']);
 select * into v from public.sgp_aluminio_pendientes where id_pendiente=p_id for update;
 if not found then raise exception 'Pendiente no encontrado'; end if;
 if v.estado<>'PENDIENTE' or coalesce(v.estado_repo,'PENDIENTE')='PICKING' then raise exception 'El pendiente ya no está activo'; end if;
 if coalesce(v.validacion_estado,'POR_VALIDAR')='VALIDADO' then raise exception 'El pendiente ya está VALIDADO'; end if;
 if v_fab is null then raise exception 'Debes confirmar la fabricación'; end if;
 if p_longitud is null or p_longitud<=0 then raise exception 'Debes confirmar una longitud válida'; end if;
 v_res:=coalesce(nullif(trim(coalesce(p_reserva,'')),''),v.reserva);
 v_acab:=coalesce(v_acab,nullif(trim(coalesce(v.acabado_pendiente,'')),''));
 if v_acab is null then raise exception 'Debes confirmar el acabado'; end if;

 if v.key_produccion is not null and not exists(
   select 1 from public.sgp_produccion_reservas_v r
   where r.key_produccion=v.key_produccion and r.reserva=v_res
     and (r.acabado_reserva is null or upper(trim(r.acabado_reserva))=upper(trim(v_acab)))
 ) then raise exception 'La combinación reserva/acabado seleccionada no pertenece a esta producción'; end if;

 v_prod_num:=nullif(substring(coalesce(v.produccion,'') from '^[[:space:]]*([0-9]+)'),'');
 select exists(select 1 from public.sgp_aluminio a where a.activo='SI' and a.tipo_pieza='PANEL'
   and trim(coalesce(a.codigo_sap,''))=trim(coalesce(v.perfil,''))
   and ((v.key_produccion is not null and a.key_produccion=v.key_produccion) or a.produccion=v.produccion))
 into v_exact;
 select exists(select 1 from public.sgp_aluminio a where a.activo='SI' and a.tipo_pieza='PANEL'
   and trim(coalesce(a.codigo_sap,''))=trim(coalesce(v.perfil,''))
   and ((v.key_produccion is not null and a.key_produccion=v.key_produccion) or a.produccion=v.produccion
        or (not v_exact and v_prod_num is not null and substring(coalesce(a.produccion,'') from '^[[:space:]]*([0-9]+)')=v_prod_num)))
 into v_has_source;
 if v_has_source and not exists(
   select 1 from public.sgp_aluminio a
   where a.activo='SI' and a.tipo_pieza='PANEL'
     and trim(coalesce(a.codigo_sap,''))=trim(coalesce(v.perfil,''))
     and lower(trim(coalesce(a.fabricacion,'')))=lower(trim(v_fab))
     and a.longitud=p_longitud
     and upper(trim(coalesce(a.acabado,'')))=upper(trim(v_acab))
     and ((v.key_produccion is not null and a.key_produccion=v.key_produccion) or a.produccion=v.produccion
          or (not v_exact and v_prod_num is not null and substring(coalesce(a.produccion,'') from '^[[:space:]]*([0-9]+)')=v_prod_num))
 ) then raise exception 'Los datos a validar no corresponden a una pieza registrada en esta orden'; end if;

 old_data:=jsonb_build_object('fabricacion',v.fabricacion,'longitud',v.longitud,'reserva',v.reserva,'acabado',v.acabado_pendiente,'validacion_estado',v.validacion_estado);
 update public.sgp_aluminio_pendientes
 set fabricacion=v_fab,longitud=p_longitud,reserva=v_res,acabado_pendiente=v_acab,
     validacion_estado='VALIDADO',validado_por=u,fecha_validacion=now(),
     observacion_validacion=nullif(trim(coalesce(p_observacion,'')),'')
 where id_pendiente=p_id;
 new_data:=jsonb_build_object('fabricacion',v_fab,'longitud',p_longitud,'reserva',v_res,'acabado',v_acab,'validacion_estado','VALIDADO');
 insert into public.sgp_aluminio_pendientes_historial(id_pendiente,estado_anterior,estado_nuevo,usuario,observacion,tipo_evento,datos_anteriores,datos_nuevos)
 values(p_id,v.estado_repo,v.estado_repo,u,coalesce(nullif(trim(coalesce(p_observacion,'')),''),'Validación física del PDT'),'VALIDACION_PDT',old_data,new_data);
 return jsonb_build_object('ok',true,'validacion_estado','VALIDADO','validado_por',u);
end $function$

CREATE OR REPLACE FUNCTION public.sgp_aluminio_pendiente_piezas(p_token text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 u text; v public.sgp_aluminio_pendientes%rowtype;
 v_prod_num text; v_exact boolean:=false;
begin
 u:=public.sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR','LIDER MECANIZADO','LIDER','LIDER LINEA','SUPERVISOR DE PICKING','PATINADOR','CONSULTA']);
 select * into v from public.sgp_aluminio_pendientes where id_pendiente=p_id;
 if not found then raise exception 'Pendiente no encontrado'; end if;
 v_prod_num:=nullif(substring(coalesce(v.produccion,'') from '^[[:space:]]*([0-9]+)'),'');
 select exists(
   select 1 from public.sgp_aluminio a
   where a.activo='SI' and a.tipo_pieza='PANEL'
     and trim(coalesce(a.codigo_sap,''))=trim(coalesce(v.perfil,''))
     and ((v.key_produccion is not null and a.key_produccion=v.key_produccion) or a.produccion=v.produccion)
 ) into v_exact;
 return coalesce((
   select jsonb_agg(jsonb_build_object(
     'marca',x.marca,'fabricacion',x.fabricacion,'longitud',x.longitud,'acabado',x.acabado,
     'cantidad',x.cantidad,'seleccion_actual',
       lower(trim(coalesce(x.fabricacion,'')))=lower(trim(coalesce(v.fabricacion,'')))
       and x.longitud is not distinct from v.longitud
       and (v.acabado_pendiente is null or upper(trim(coalesce(x.acabado,'')))=upper(trim(v.acabado_pendiente)))
   ) order by x.fabricacion,x.longitud,x.acabado)
   from (
     select string_agg(distinct nullif(trim(a.marca),''),' / ' order by nullif(trim(a.marca),'')) marca,
            a.fabricacion,a.longitud,a.acabado,sum(coalesce(a.cantidad,0)) cantidad
     from public.sgp_aluminio a
     where a.activo='SI' and a.tipo_pieza='PANEL'
       and trim(coalesce(a.codigo_sap,''))=trim(coalesce(v.perfil,''))
       and (
         (v.key_produccion is not null and a.key_produccion=v.key_produccion)
         or a.produccion=v.produccion
         or (not v_exact and v_prod_num is not null and substring(coalesce(a.produccion,'') from '^[[:space:]]*([0-9]+)')=v_prod_num)
       )
     group by a.fabricacion,a.longitud,a.acabado
   )x
 ),'[]'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.sgp_aluminio_pendiente_editar_v2(p_token text, p_id uuid, p_nc text DEFAULT NULL::text, p_fabricacion text DEFAULT NULL::text, p_longitud numeric DEFAULT NULL::numeric, p_reserva text DEFAULT NULL::text, p_acabado text DEFAULT NULL::text, p_observacion text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare out jsonb; v_obs text:=nullif(trim(coalesce(p_observacion,'')),'');
BEGIN
   PERFORM 1 FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
   IF EXISTS(SELECT 1 FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id AND contrato_pdt='V2')
   THEN RAISE EXCEPTION 'PDT_V2_USAR_RPC_DEDICADA'; END IF;

 out:=public.sgp_aluminio_pendiente_editar(p_token,p_id,p_nc,p_fabricacion,p_longitud,p_reserva,p_acabado);
 if v_obs is not null then
   update public.sgp_aluminio_pendientes_historial h
      set observacion=v_obs
    where h.id=(
      select h2.id from public.sgp_aluminio_pendientes_historial h2
      where h2.id_pendiente=p_id and h2.tipo_evento='EDICION_PDT'
      order by h2.id desc limit 1
    );
 end if;
 return out;
end $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_validar_rol_real(p_token text, p_roles text[])
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE sesion jsonb; rol_real text;
BEGIN
 IF p_token IS NULL OR p_roles IS NULL OR cardinality(p_roles)=0 THEN
  RAISE EXCEPTION 'PDT_ROL_REAL_NO_AUTORIZADO';
 END IF;
 sesion:=to_jsonb(public.sgp_sesion_actual(p_token));
 IF jsonb_typeof(sesion) IS DISTINCT FROM 'object' OR sesion->'valida' IS DISTINCT FROM 'true'::jsonb THEN
  RAISE EXCEPTION 'PDT_SESION_NO_VALIDA';
 END IF;
 rol_real:=upper(btrim(sesion->>'rol'));
 IF rol_real IS NULL OR NOT coalesce(rol_real=ANY(p_roles),false) THEN
  RAISE EXCEPTION 'PDT_ROL_REAL_NO_AUTORIZADO';
 END IF;
 -- Preserve legacy actor resolution only AFTER the exact-role check.
 RETURN public.sgp_validar_sesion_rol(p_token,p_roles);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_aluminio_pendiente_revertir_avance_v1(p_token text, p_id uuid, p_movimiento uuid, p_clave uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 u text;
 p public.sgp_aluminio_pendientes%rowtype;
 a public.sgp_aluminio_pendiente_movimientos%rowtype;
 e public.sgp_aluminio_pendiente_movimientos%rowtype;
 nuevo uuid;
BEGIN
 u := public.sgp_pdt_validar_rol_real(p_token, ARRAY['ADMINISTRADOR','COORDINADOR','LIDER MECANIZADO','LIDER']);
 IF p_id IS NULL OR p_movimiento IS NULL OR p_clave IS NULL OR nullif(btrim(p_motivo),'') IS NULL
 THEN RAISE EXCEPTION 'Parametros invalidos'; END IF;
 SELECT * INTO p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Pendiente inexistente'; END IF;
 SELECT * INTO e FROM public.sgp_aluminio_pendiente_movimientos WHERE idempotency_key=p_clave;
 IF FOUND THEN
  IF e.tipo <> 'REVERSO' OR e.id_pendiente <> p_id OR e.id_movimiento_revertido <> p_movimiento OR e.observacion IS DISTINCT FROM p_motivo
  THEN RAISE EXCEPTION 'Clave reutilizada'; END IF;
  RETURN jsonb_build_object('ok',true,'duplicado',true,'id_movimiento',e.id_movimiento);
 END IF;
 IF p.estado <> 'PENDIENTE' OR p.estado_repo = 'PICKING' OR p.fecha_cierre IS NOT NULL
 THEN RAISE EXCEPTION 'Pendiente no apto'; END IF;
 SELECT * INTO a FROM public.sgp_aluminio_pendiente_movimientos
 WHERE id_movimiento=p_movimiento AND id_pendiente=p_id AND tipo='AVANCE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Avance inexistente'; END IF;
 IF EXISTS (SELECT 1 FROM public.sgp_aluminio_pendiente_movimientos WHERE id_movimiento_revertido=p_movimiento)
 THEN RAISE EXCEPTION 'Avance ya revertido'; END IF;
 IF p.contrato_pdt<>'V2' OR p.validacion_estado<>'VALIDADO' THEN RAISE EXCEPTION 'PDT no V2 validado'; END IF;
 IF (SELECT coalesce(sum(CASE WHEN tipo='AVANCE' THEN cantidad ELSE -cantidad END),0)
 FROM public.sgp_aluminio_pendiente_movimientos WHERE id_detalle=a.id_detalle)-a.cantidad
 <public.sgp_pdt_comprometido(a.id_detalle) THEN RAISE EXCEPTION 'Reverso afecta entrega Picking'; END IF;
 INSERT INTO public.sgp_aluminio_pendiente_movimientos
 (id_pendiente,id_detalle,tipo,cantidad,id_movimiento_revertido,idempotency_key,usuario,turno,fecha_operativa,observacion)
 VALUES (p_id,a.id_detalle,'REVERSO',a.cantidad,p_movimiento,p_clave,u,a.turno,a.fecha_operativa,p_motivo)
 RETURNING id_movimiento INTO nuevo;
 INSERT INTO public.sgp_aluminio_pendientes_historial (id_pendiente,usuario,observacion,tipo_evento,estado_anterior,estado_nuevo,datos_nuevos)
 VALUES (p_id,u,p_motivo,'REVERSO_AVANCE_PDT',p.estado_repo,CASE WHEN p.estado_repo='PROCESADO' THEN 'MECANIZADO' ELSE p.estado_repo END,jsonb_build_object('original',p_movimiento,'reverso',nuevo,'cantidad',a.cantidad));
 IF p.estado_repo='PROCESADO' THEN
  UPDATE public.sgp_aluminio_pendientes SET estado_repo='MECANIZADO',usuario_estado=u,fecha_estado=now() WHERE id_pendiente=p_id;
 END IF;
 RETURN jsonb_build_object('ok',true,'duplicado',false,'id_movimiento',nuevo);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_aluminio_pendiente_nc_vincular_v1(p_token text, p_id uuid, p_ncs text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 u text; p public.sgp_aluminio_pendientes%rowtype;
 snap jsonb; n text; canonical text; matches integer; inserted integer; added text[]:=ARRAY[]::text[]; ncs text[]:=ARRAY[]::text[];
BEGIN
 u:=public.sgp_validar_sesion_rol(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','PATINADOR']);
 IF p_id IS NULL OR p_ncs IS NULL OR cardinality(p_ncs) NOT BETWEEN 1 AND 30
 THEN RAISE EXCEPTION 'Listado NC invalido'; END IF;
 SELECT * INTO p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
 IF NOT FOUND OR p.estado <> 'PENDIENTE' OR p.fecha_cierre IS NOT NULL OR p.estado_repo='PICKING' THEN RAISE EXCEPTION 'Pendiente no activo'; END IF;
 FOREACH n IN ARRAY p_ncs LOOP
  n:=btrim(n);
  IF n IS NULL OR length(n) NOT BETWEEN 1 AND 120 OR n ~ '[[:cntrl:]]' THEN RAISE EXCEPTION 'Consecutivo NC invalido'; END IF;
  SELECT count(DISTINCT nc.consecutivo),min(nc.consecutivo) INTO matches,canonical
 FROM public.sgp_nc_aluminio nc WHERE nc.consecutivo=n OR nc.cod_nc=n;
 IF matches>1 THEN RAISE EXCEPTION 'NC ambigua: %',n; END IF;
 IF matches=1 THEN n:=canonical; END IF;
  IF NOT (n=ANY(ncs)) THEN ncs:=array_append(ncs,n); END IF;
 END LOOP;
 FOREACH n IN ARRAY ncs LOOP
  SELECT to_jsonb(nc) INTO snap FROM public.sgp_nc_aluminio nc WHERE nc.consecutivo=n
  ORDER BY nc.fecha_actualizacion DESC NULLS LAST,nc.creacion DESC NULLS LAST LIMIT 1;
  IF snap IS NOT NULL THEN
   INSERT INTO public.sgp_aluminio_pendiente_ncs(id_pendiente,consecutivo,enlazado_por,snapshot)
   VALUES(p_id,n,u,snap) ON CONFLICT DO NOTHING;
   GET DIAGNOSTICS inserted=ROW_COUNT;
  ELSE
   SELECT CASE WHEN EXISTS (SELECT 1 FROM public.sgp_aluminio_pendientes_historial h CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(h.datos_nuevos->'ncs')='array' THEN h.datos_nuevos->'ncs' ELSE '[]'::jsonb END) x(ref) WHERE h.id_pendiente=p_id AND h.tipo_evento IN ('REGISTRO_MULTIORIGEN_V4','VINCULACION_NC_PDT') AND x.ref=n) OR n=ANY(regexp_split_to_array(coalesce(p.nc,''),'[,;]')) THEN 0 ELSE 1 END INTO inserted;
  END IF;
  IF inserted=1 THEN added:=array_append(added,n); END IF;
 END LOOP;
 IF cardinality(added)>0 THEN
 INSERT INTO public.sgp_aluminio_pendientes_historial(id_pendiente,estado_nuevo,usuario,tipo_evento,datos_nuevos)
 VALUES(p_id,p.estado,u,'VINCULACION_NC_PDT',jsonb_build_object('ncs',added,'referencias_solicitadas',p_ncs));
 END IF;
 RETURN jsonb_build_object('ok',true,'ncs',ncs,'agregadas',added,'duplicado',cardinality(added)=0);
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_multiorigen.registrar(p_token text, p_origen text, p_contexto jsonb, p_piezas jsonb, p_evento uuid, p_entrega uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor text; sources jsonb; row jsonb; source jsonb; ctx jsonb; id uuid; ids jsonb:='[]'; n integer; quantity numeric; nc text; snap jsonb; matches integer; ncs jsonb; nc_item jsonb; raw_nc text; seen_raw text[]; seen_links text[];
BEGIN
 actor:=sgp_pdt_multiorigen.actor(p_token,p_origen);
 IF jsonb_typeof(p_piezas) IS DISTINCT FROM 'array' OR jsonb_array_length(p_piezas) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'PDT_PIEZAS_REQUERIDAS'; END IF;
 IF (SELECT count(DISTINCT jsonb_build_array(x->>'id_pieza',x->>'key_produccion',x->>'reserva')) FROM jsonb_array_elements(p_piezas) x)<>jsonb_array_length(p_piezas) THEN RAISE EXCEPTION 'PDT_PIEZA_REPETIDA_EN_EVENTO'; END IF;
 sources:=sgp_pdt_multiorigen.fuentes(p_token,p_origen,p_contexto);
 FOR row IN SELECT value FROM jsonb_array_elements(p_piezas) LOOP
 IF nullif(row->>'id_pieza','') IS NULL OR nullif(row->>'key_produccion','') IS NULL OR nullif(row->>'reserva','') IS NULL THEN RAISE EXCEPTION 'PDT_IDENTIDAD_REQUERIDA'; END IF;
 SELECT count(*),jsonb_agg(x)->0 INTO n,source FROM jsonb_array_elements(sources) x
 WHERE x->>'id_pieza'=row->>'id_pieza' AND x->>'key_produccion'=row->>'key_produccion' AND x->>'reserva'=row->>'reserva'
 AND x->>'codigo_sap'=row->>'perfil' AND x->>'fabricacion' IS NOT DISTINCT FROM row->>'fabricacion'
 AND (x->>'longitud')::numeric=(row->>'longitud')::numeric
 AND x->>'acabado'=row->>'acabado';
 IF n<>1 THEN RAISE EXCEPTION 'PDT_PIEZA_NO_CORRESPONDE_AL_CONTEXTO'; END IF;
 -- Locks prevent a concurrent source/master/relationship edit from silently
 -- changing the identity during the transaction (the view relations are asserted
 -- again by the strict identity trigger on INSERT).
 PERFORM 1 FROM public.sgp_aluminio WHERE id_pieza=row->>'id_pieza' FOR SHARE;
 PERFORM 1 FROM public.sgp_maestro_piezas WHERE codigo_sap=row->>'perfil' FOR SHARE;
 PERFORM 1 FROM public.sgp_producciones WHERE key_produccion=row->>'key_produccion' FOR SHARE;
 ctx:=public.sgp_pdt_contexto_internal_v3(row->>'reserva',row->>'perfil',p_contexto->>'produccion',row->>'acabado',row->>'id_pieza',row->>'key_produccion',row->>'reserva_principal',(row->>'longitud')::numeric);
 SELECT ctx||jsonb_build_object('id_carga',a.id_carga,'fila_origen',a.fila_origen) INTO ctx FROM public.sgp_aluminio a WHERE a.id_pieza=row->>'id_pieza';
 quantity:=(row->>'cantidad')::numeric; nc:=nullif(btrim(row->>'nc'),'');
 IF quantity IS NULL OR quantity<=0 OR quantity<>trunc(quantity) OR quantity>2147483647 OR (SELECT cantidad FROM public.sgp_aluminio WHERE id_pieza=row->>'id_pieza') IS NULL OR quantity>(SELECT cantidad FROM public.sgp_aluminio WHERE id_pieza=row->>'id_pieza') THEN RAISE EXCEPTION 'PDT_CANTIDAD_INVALIDA'; END IF;
 IF p_origen IN ('ENSAMBLE','EMPAQUE') AND nc IS NULL THEN RAISE EXCEPTION 'PDT_NC_OBLIGATORIA'; END IF;
 IF nc IS NOT NULL AND (length(nc)>120 OR nc~'[[:cntrl:]]') THEN RAISE EXCEPTION 'PDT_NC_INVALIDA'; END IF;
 IF row ? 'ncs' THEN
  IF p_origen<>'PICKING' OR jsonb_typeof(row->'ncs') IS DISTINCT FROM 'array'
  THEN RAISE EXCEPTION 'PDT_NCS_INVALIDAS'; END IF;
  IF jsonb_array_length(row->'ncs')>20 THEN RAISE EXCEPTION 'PDT_NCS_INVALIDAS'; END IF;
  ncs:=row->'ncs';
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(ncs) x
   WHERE jsonb_typeof(x.value)<>'string' OR btrim(x.value #>> '{}')=''
   OR length(btrim(x.value #>> '{}'))>120 OR btrim(x.value #>> '{}')~'[[:cntrl:]]')
  THEN RAISE EXCEPTION 'PDT_NC_INVALIDA'; END IF;
  IF (jsonb_array_length(ncs)=0 AND nc IS NOT NULL)
   OR (jsonb_array_length(ncs)>0 AND nc IS DISTINCT FROM btrim(ncs->>0))
  THEN RAISE EXCEPTION 'PDT_NC_PRINCIPAL_NO_COINCIDE'; END IF;
 ELSE
  ncs:=CASE WHEN nc IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(nc) END;
 END IF;
 INSERT INTO public.sgp_aluminio_pendientes(reserva,reserva_principal,key_produccion,es_reserva_compartida,acabado_pendiente,produccion,perfil,cantidad,longitud,origen,causa,observacion,usuario_reporte,id_pieza,marca,fabricacion,nc,contrato_pdt)
 VALUES(ctx->>'reserva',ctx->>'reserva_principal',ctx->>'key_produccion',coalesce((ctx->>'es_reserva_compartida')::boolean,false),ctx->>'acabado',ctx->>'produccion',row->>'perfil',quantity,(ctx->>'longitud')::numeric,p_origen,CASE p_origen WHEN 'PICKING' THEN 'FALTANTE_ENTREGA' ELSE 'DANO_'||p_origen END,nullif(btrim(row->>'observacion'),''),actor,ctx->>'id_pieza',ctx->>'marca',ctx->>'fabricacion',nc,'V2') RETURNING id_pendiente INTO id;
 INSERT INTO sgp_pdt_multiorigen.detalles VALUES(id,p_evento,p_entrega,ctx);
 seen_raw:=ARRAY[]::text[]; seen_links:=ARRAY[]::text[];
 FOR nc_item IN SELECT value FROM jsonb_array_elements(ncs) LOOP
  raw_nc:=btrim(nc_item #>> '{}');
  IF raw_nc=ANY(seen_raw) THEN RAISE EXCEPTION 'PDT_NC_DUPLICADA'; END IF;
  seen_raw:=array_append(seen_raw,raw_nc);
  SELECT count(DISTINCT consecutivo) INTO matches FROM public.sgp_nc_aluminio WHERE consecutivo=raw_nc OR cod_nc=raw_nc;
  IF matches>1 THEN RAISE EXCEPTION 'PDT_NC_AMBIGUA'; END IF;
  IF matches=1 THEN
   SELECT to_jsonb(c) INTO snap FROM public.sgp_nc_aluminio c WHERE consecutivo=raw_nc OR cod_nc=raw_nc ORDER BY fecha_actualizacion DESC NULLS LAST,creacion DESC NULLS LAST LIMIT 1;
   IF snap->>'consecutivo'=ANY(seen_links) THEN RAISE EXCEPTION 'PDT_NC_DUPLICADA'; END IF;
   seen_links:=array_append(seen_links,snap->>'consecutivo');
   INSERT INTO public.sgp_aluminio_pendiente_ncs(id_pendiente,consecutivo,enlazado_por,snapshot) VALUES(id,snap->>'consecutivo',actor,snap);
  END IF;
 END LOOP;
 INSERT INTO public.sgp_aluminio_pendientes_historial(id_pendiente,usuario,estado_anterior,estado_nuevo,tipo_evento,datos_nuevos)
 VALUES(id,actor,NULL,'PENDIENTE','REGISTRO_MULTIORIGEN_V4',jsonb_build_object('origen',p_origen,'id_evento',p_evento,'id_entrega',p_entrega,'fuente',ctx,'nc',nc,'ncs',ncs));
 ids:=ids||jsonb_build_array(id);
 END LOOP;
 RETURN jsonb_build_object('ok',true,'contract_version',4,'ids_pendientes',ids);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_registrar_v4(p_token text, p_origen text, p_contexto jsonb, p_piezas jsonb, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor text; request jsonb; prior sgp_pdt_multiorigen.eventos%rowtype; result jsonb; delivery uuid; program public.sgp_mecanizado_programacion%rowtype; row jsonb; complete boolean;
BEGIN
 actor:=sgp_pdt_multiorigen.actor(p_token,p_origen);
 IF p_idempotency_key IS NULL THEN RAISE EXCEPTION 'PDT_EVENTO_REQUERIDO'; END IF;
 request:=jsonb_build_object('origen',p_origen,'contexto',p_contexto,'piezas',p_piezas);
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_idempotency_key::text,0));
 SELECT * INTO prior FROM sgp_pdt_multiorigen.eventos WHERE id_evento=p_idempotency_key;
 IF FOUND THEN
 IF prior.usuario IS DISTINCT FROM actor OR prior.solicitud IS DISTINCT FROM request THEN RAISE EXCEPTION 'PDT_IDEMPOTENCIA_REUTILIZADA'; END IF;
 RETURN prior.respuesta||jsonb_build_object('duplicado',true);
 END IF;
 IF p_origen='PICKING' THEN
 SELECT * INTO STRICT program FROM public.sgp_mecanizado_programacion WHERE id_programacion=(p_contexto->>'id_programacion')::uuid AND estado<>'CANCELADA' FOR UPDATE;
 IF nullif(p_contexto->>'produccion','') IS NULL OR p_contexto->>'completa' NOT IN ('true','false') OR p_contexto->>'completa' IS NULL THEN RAISE EXCEPTION 'PDT_ENTREGA_INVALIDA'; END IF;
 IF p_contexto->>'turno' NOT IN ('TURNO 1','TURNO 2') OR p_contexto->>'turno' IS NULL OR nullif(p_contexto->>'fecha_entrega','') IS NULL THEN RAISE EXCEPTION 'PDT_FECHA_TURNO_REQUERIDOS'; END IF;
 complete:=(p_contexto->>'completa')::boolean;
 IF complete THEN
 IF p_piezas IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION 'PDT_ENTREGA_COMPLETA_CON_FALTANTES'; END IF;
 -- Preserve installed complete-delivery behavior and its duplicate trigger.
 result:=sgp_pdt_compat_91.sgp_picking_entrega_orden(p_token,program.id_programacion,p_contexto->>'produccion',true,p_contexto->>'observacion','[]'::jsonb,(p_contexto->>'fecha_entrega')::date,p_contexto->>'turno');
 ELSE
 delivery:=gen_random_uuid();
 INSERT INTO public.sgp_picking_entregas(id_entrega,id_programacion,produccion,completa,estado,observacion,usuario_entrega,fecha_entrega,fecha_operativa,turno_entrega)
 VALUES(delivery,program.id_programacion,p_contexto->>'produccion',false,'PENDIENTE_VALIDACION',nullif(btrim(p_contexto->>'observacion'),''),actor,now(),(p_contexto->>'fecha_entrega')::date,p_contexto->>'turno');
 result:=sgp_pdt_multiorigen.registrar(p_token,p_origen,p_contexto,p_piezas,p_idempotency_key,delivery);
 FOR row IN SELECT value FROM jsonb_array_elements(p_piezas) LOOP
 INSERT INTO public.sgp_picking_faltantes(id_entrega,id_pieza,produccion,perfil,marca,fabricacion,longitud,cantidad,observacion,nc,reserva_pendiente,acabado_pendiente)
 VALUES(delivery,row->>'id_pieza',p_contexto->>'produccion',row->>'perfil',row->>'marca',row->>'fabricacion',(row->>'longitud')::numeric,(row->>'cantidad')::numeric,nullif(btrim(row->>'observacion'),''),nullif(btrim(row->>'nc'),''),row->>'reserva',row->>'acabado');
 END LOOP;
 result:=result||jsonb_build_object('id_entrega',delivery,'estado','PENDIENTE_VALIDACION');
 END IF;
 ELSE
 result:=sgp_pdt_multiorigen.registrar(p_token,p_origen,p_contexto,p_piezas,p_idempotency_key);
 END IF;
 INSERT INTO sgp_pdt_multiorigen.eventos VALUES(p_idempotency_key,actor,request,result,now());
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_multiorigen.fuentes(p_token text, p_origen text, p_contexto jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE program public.sgp_mecanizado_programacion%rowtype; allowed jsonb; result jsonb;
BEGIN
 PERFORM sgp_pdt_multiorigen.actor(p_token,p_origen);
 IF nullif(btrim(p_contexto->>'produccion'),'') IS NULL THEN RAISE EXCEPTION 'PDT_PRODUCCION_REQUERIDA'; END IF;
 IF p_origen='PICKING' THEN
 SELECT * INTO STRICT program FROM public.sgp_mecanizado_programacion WHERE id_programacion=(p_contexto->>'id_programacion')::uuid AND estado<>'CANCELADA' FOR SHARE;
 allowed:=public.sgp_picking_piezas_panel(p_token,program.id_programacion,p_contexto->>'produccion');
 ELSE
 IF nullif(p_contexto->>'key_produccion','') IS NULL THEN RAISE EXCEPTION 'PDT_CLAVE_REQUERIDA'; END IF;
 END IF;
 SELECT coalesce(jsonb_agg(x ORDER BY x->>'codigo_sap',x->>'fabricacion',x->>'longitud',x->>'id_pieza'),'[]'::jsonb) INTO result
 FROM (SELECT DISTINCT x||jsonb_build_object('id_carga',a.id_carga,'fila_origen',a.fila_origen) AS x FROM public.sgp_produccion_reservas_v r
 CROSS JOIN LATERAL public.sgp_pdt_origenes_internal_v3(r.reserva,NULL,p_contexto->>'produccion',NULL,NULL) x
 JOIN public.sgp_aluminio a ON a.id_pieza=x->>'id_pieza'
 WHERE r.produccion=p_contexto->>'produccion' AND r.key_produccion=x->>'key_produccion' AND r.reserva=x->>'reserva'
 AND x->>'tipo_pieza'='PANEL' AND x->>'id_linea'='PANELES_2'
 AND (nullif(p_contexto->>'reserva','') IS NULL OR x->>'reserva'=p_contexto->>'reserva')
 AND (nullif(p_contexto->>'key_produccion','') IS NULL OR x->>'key_produccion'=p_contexto->>'key_produccion')
 AND (p_origen<>'PICKING' OR (
 coalesce(x->>'reserva_principal',x->>'reserva')=program.reserva
 AND upper(btrim(x->>'sistema'))=upper(btrim(program.sistema))
 AND upper(btrim(x->>'acabado'))=upper(btrim(program.acabado))
 AND EXISTS(SELECT 1 FROM jsonb_array_elements(allowed) a WHERE a->>'id_pieza'=x->>'id_pieza')))) q;
 IF jsonb_array_length(result)>1000 THEN RAISE EXCEPTION 'PDT_FUENTES_EXCEDEN_LIMITE'; END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_multiorigen.original_sgp_pdt_fuentes_v2(p_token text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p public.sgp_aluminio_pendientes%rowtype;
BEGIN
 PERFORM public.sgp_validar_sesion_rol(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','RECEPCION','LIDER LINEA','SUPERVISOR DE PICKING']);
 SELECT * INTO STRICT p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id;
 PERFORM public.sgp_pdt_exigir_panel_v3(p_id);
 IF p.key_produccion IS NULL THEN RAISE EXCEPTION 'Producción sin identidad'; END IF;
 RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id_pieza',a.id_pieza,'id_carga',a.id_carga,'fila_origen',a.fila_origen,'fabricacion',a.fabricacion,
  'longitud',a.longitud::text,'acabado',a.acabado,'marca',a.marca,'uso',a.uso,'cantidad',a.cantidad) ORDER BY a.fabricacion,a.longitud,a.acabado,a.id_pieza)
 FROM public.sgp_aluminio a JOIN public.sgp_producciones prod ON prod.key_produccion=a.key_produccion
 WHERE prod.id_linea='PANELES_2' AND btrim(a.produccion)=btrim(p.produccion) AND a.key_produccion=p.key_produccion AND a.activo='SI' AND a.tipo_pieza='PANEL'
 AND (nullif(btrim(coalesce(p.acabado_pendiente,'')),'') IS NULL OR upper(btrim(a.acabado))=upper(btrim(p.acabado_pendiente)))
 AND EXISTS(SELECT 1 FROM public.sgp_produccion_reservas_v r WHERE r.key_produccion=p.key_produccion AND r.reserva=p.reserva AND (r.acabado_reserva IS NULL OR upper(btrim(r.acabado_reserva))=upper(btrim(a.acabado))))
 AND upper(btrim(a.sistema))=upper(btrim(prod.sistema)) AND btrim(a.codigo_sap)=btrim(p.perfil)),'[]'::jsonb);
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_multiorigen.nuevo_sgp_pdt_fuentes_v2(p_token text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
