CREATE OR REPLACE FUNCTION sgp_pdt_multiorigen.grouped_nuevo_validar(p_token text, p_id uuid, p_detalles jsonb, p_reserva text DEFAULT NULL::text, p_observacion text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_usuario text; v_p public.sgp_aluminio_pendientes%rowtype;
 v_row jsonb; v_fab text; v_acab text; v_long numeric; v_cant integer;
 v_total bigint:=0; v_count integer:=0; v_first jsonb; v_source integer; v_detalle uuid; v_a public.sgp_aluminio%rowtype;
 v_key text; v_keys text[]:=array[]::text[]; v_out jsonb; v_correction boolean; v_res text; v_acab_res text;
BEGIN
 v_usuario:=public.sgp_validar_sesion_rol(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','LIDER LINEA','SUPERVISOR DE PICKING','RECEPCION']);
 SELECT * INTO v_p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
 IF NOT FOUND OR v_p.estado<>'PENDIENTE' OR v_p.fecha_cierre IS NOT NULL OR coalesce(v_p.estado_repo,'PENDIENTE')='PICKING' OR coalesce(v_p.validacion_estado,'POR_VALIDAR')='VALIDADO'
 THEN RAISE EXCEPTION 'Pendiente no activo o ya validado'; END IF;
 IF p_detalles IS NULL OR jsonb_typeof(p_detalles)<>'array' OR jsonb_array_length(p_detalles) NOT BETWEEN 1 AND 100
 THEN RAISE EXCEPTION 'Se requiere entre 1 y 100 fabricaciones'; END IF;
 IF EXISTS (SELECT 1 FROM public.sgp_aluminio_pendiente_movimientos WHERE id_pendiente=p_id)
 THEN RAISE EXCEPTION 'No se puede revalidar un pendiente con movimientos'; END IF;
 FOR v_row IN SELECT value FROM jsonb_array_elements(p_detalles)
 LOOP
  v_count:=v_count+1;
  v_fab:=nullif(btrim(v_row->>'fabricacion'),'');
  v_acab:=nullif(btrim(v_row->>'acabado'),'');
  IF v_row->>'longitud' !~ '^[0-9]+([.][0-9]+)?$'
    OR v_row->>'cantidad' !~ '^[0-9]+$'
  THEN RAISE EXCEPTION 'Longitud y cantidad deben ser numéricas'; END IF;
  v_long:=(v_row->>'longitud')::numeric;
  IF length(v_row->>'cantidad')>10 OR (v_row->>'cantidad')::numeric>2147483647 THEN RAISE EXCEPTION 'Cantidad fuera de rango'; END IF;
  v_cant:=(v_row->>'cantidad')::integer;
  IF v_fab IS NULL OR v_acab IS NULL OR v_long<=0 OR v_cant<=0
  THEN RAISE EXCEPTION 'Fabricación, acabado, longitud y cantidad obligatorios'; END IF;
  v_key:=lower(v_fab)||'|'||v_long::text||'|'||upper(v_acab);
  IF nullif(v_row->>'id_pieza','') IS NOT NULL THEN RAISE EXCEPTION 'Modo fuente mixta no permitido'; END IF;
  IF v_key=ANY(v_keys) THEN RAISE EXCEPTION 'Fabricación repetida'; END IF;
  v_keys:=array_append(v_keys,v_key);
  IF v_count=1 THEN v_first:=v_row; END IF;
  v_total:=v_total+v_cant;
  IF v_total>2147483647 THEN RAISE EXCEPTION 'Cantidad fuera de rango'; END IF;
 PERFORM public.sgp_pdt_exigir_panel_v3(p_id);
  IF nullif(btrim(v_p.key_produccion),'') IS NULL THEN RAISE EXCEPTION 'Identidad producción no resuelta'; END IF;
  -- Direct, physical-source validation as in production. A legacy imported
  -- source key may point at FRAME, but its base ID and PANEL master must prove
  -- ONE matching PANEL target. No name-only match and no generic source helper.
  SELECT count(*) INTO v_source FROM public.sgp_aluminio a
  JOIN public.sgp_producciones origin ON origin.key_produccion=a.key_produccion
  JOIN public.sgp_producciones prod ON prod.id=origin.id AND nullif(btrim(origin.id),'') IS NOT NULL
  JOIN public.sgp_maestro_piezas m ON m.codigo_sap=a.codigo_sap
  WHERE a.activo='SI' AND a.tipo_pieza='PANEL'
   AND m.activo='SI' AND m.tipo_pieza='PANEL' AND m.destino_productivo='PANEL'
   AND origin.id_linea IN ('PANELES_2','FRAMES_2') AND prod.id_linea='PANELES_2'
   AND prod.key_produccion=v_p.key_produccion
   AND btrim(a.produccion)=btrim(v_p.produccion) AND btrim(origin.produccion)=btrim(prod.produccion)
   AND upper(btrim(a.sistema))=upper(btrim(prod.sistema)) AND upper(btrim(origin.sistema))=upper(btrim(prod.sistema))
   AND btrim(a.codigo_sap)=btrim(v_p.perfil)
   AND lower(btrim(a.fabricacion))=lower(v_fab) AND a.longitud=v_long AND upper(btrim(a.acabado))=upper(v_acab)
   AND (nullif(btrim(v_p.acabado_pendiente),'') IS NULL OR upper(btrim(a.acabado))=upper(btrim(v_p.acabado_pendiente)))
   AND EXISTS(SELECT 1 FROM public.sgp_produccion_reservas_v r
    WHERE r.key_produccion=prod.key_produccion AND r.reserva=coalesce(nullif(btrim(p_reserva),''),v_p.reserva)
    AND (NOT coalesce(r.es_reserva_compartida,false) OR nullif(btrim(r.reserva_principal),'') IS NOT NULL)
    AND (r.acabado_reserva IS NULL OR upper(btrim(r.acabado_reserva))=upper(btrim(a.acabado))))
   AND (SELECT count(*) FROM public.sgp_producciones other WHERE other.id=origin.id AND other.id_linea='PANELES_2')=1;
  IF v_source<1 THEN RAISE EXCEPTION 'Fuente PANEL inexistente o ambigua'; END IF;
 END LOOP;
 v_correction := v_total IS DISTINCT FROM v_p.cantidad;
 IF v_correction AND nullif(btrim(coalesce(p_observacion,'')),'') IS NULL
 THEN RAISE EXCEPTION 'Corrección de cantidad requiere observación'; END IF;
 -- Dedicated validation for this new RPC. Legacy validator is not modified.
 v_res:=coalesce(nullif(btrim(coalesce(p_reserva,'')),''),v_p.reserva);
 v_acab_res:=coalesce(nullif(btrim(coalesce(v_p.acabado_pendiente,'')),''),nullif(btrim(v_first->>'acabado'),''));
 IF v_res IS NULL OR v_acab_res IS NULL THEN RAISE EXCEPTION 'Reserva y acabado obligatorios'; END IF;
 IF nullif(btrim(coalesce(v_p.key_produccion,'')),'') IS NOT NULL
 AND NOT EXISTS (SELECT 1 FROM public.sgp_produccion_reservas_v r
  WHERE r.key_produccion=v_p.key_produccion AND r.reserva=v_res
    AND (r.acabado_reserva IS NULL OR upper(btrim(r.acabado_reserva))=upper(v_acab_res)))
 THEN RAISE EXCEPTION 'Reserva/acabado no pertenece a producción'; END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_detalles) d
  WHERE upper(btrim(d->>'acabado'))<>upper(v_acab_res))
 THEN RAISE EXCEPTION 'Acabado distinto al de la reserva'; END IF;
 INSERT INTO public.sgp_aluminio_pendientes_historial
 (id_pendiente,usuario,observacion,estado_anterior,estado_nuevo,tipo_evento,datos_anteriores,datos_nuevos)
 VALUES(p_id,v_usuario,p_observacion,v_p.estado_repo,v_p.estado_repo,'VALIDACION_PDT',
  jsonb_build_object('fabricacion',v_p.fabricacion,'longitud',v_p.longitud,
   'reserva',v_p.reserva,'acabado',v_p.acabado_pendiente,'validacion_estado',v_p.validacion_estado),
  jsonb_build_object('fabricacion',v_first->>'fabricacion','reserva',v_res,
   'acabado',v_acab_res,'validacion_estado','VALIDADO'));
 FOR v_row IN SELECT value FROM jsonb_array_elements(p_detalles)
 LOOP
  v_fab:=btrim(v_row->>'fabricacion'); v_long:=(v_row->>'longitud')::numeric; v_acab:=btrim(v_row->>'acabado');
  INSERT INTO public.sgp_aluminio_pendiente_detalles
   (id_pendiente,id_pieza,fabricacion,longitud,acabado,cantidad_validada,creado_por)
  VALUES (p_id,'',v_fab,v_long,v_acab,(v_row->>'cantidad')::integer,v_usuario) RETURNING id_detalle INTO v_detalle;
  FOR v_a IN SELECT DISTINCT a.* FROM public.sgp_aluminio a
  JOIN public.sgp_producciones origin ON origin.key_produccion=a.key_produccion
  JOIN public.sgp_producciones prod ON prod.id=origin.id AND nullif(btrim(origin.id),'') IS NOT NULL
  JOIN public.sgp_maestro_piezas m ON m.codigo_sap=a.codigo_sap
  WHERE a.activo='SI' AND a.tipo_pieza='PANEL'
   AND m.activo='SI' AND m.tipo_pieza='PANEL' AND m.destino_productivo='PANEL'
   AND origin.id_linea IN ('PANELES_2','FRAMES_2') AND prod.id_linea='PANELES_2'
   AND prod.key_produccion=v_p.key_produccion
   AND btrim(a.produccion)=btrim(v_p.produccion) AND btrim(origin.produccion)=btrim(prod.produccion)
   AND upper(btrim(a.sistema))=upper(btrim(prod.sistema)) AND upper(btrim(origin.sistema))=upper(btrim(prod.sistema))
   AND btrim(a.codigo_sap)=btrim(v_p.perfil)
   AND lower(btrim(a.fabricacion))=lower(v_fab) AND a.longitud=v_long AND upper(btrim(a.acabado))=upper(v_acab)
   AND (nullif(btrim(v_p.acabado_pendiente),'') IS NULL OR upper(btrim(a.acabado))=upper(btrim(v_p.acabado_pendiente)))
   AND EXISTS(SELECT 1 FROM public.sgp_produccion_reservas_v r
    WHERE r.key_produccion=prod.key_produccion AND r.reserva=coalesce(nullif(btrim(p_reserva),''),v_p.reserva)
    AND (NOT coalesce(r.es_reserva_compartida,false) OR nullif(btrim(r.reserva_principal),'') IS NOT NULL)
    AND (r.acabado_reserva IS NULL OR upper(btrim(r.acabado_reserva))=upper(btrim(a.acabado))))
   AND (SELECT count(*) FROM public.sgp_producciones other WHERE other.id=origin.id AND other.id_linea='PANELES_2')=1 LOOP
   INSERT INTO public.sgp_pdt_fuentes(id_detalle,id_pieza,id_carga,fila_origen,snapshot)
   VALUES(v_detalle,v_a.id_pieza,v_a.id_carga,v_a.fila_origen,to_jsonb(v_a));
  END LOOP;
  IF NOT FOUND THEN RAISE EXCEPTION 'Fuentes PANEL cambiaron durante validación'; END IF;
 END LOOP;
 UPDATE public.sgp_aluminio_pendientes SET contrato_pdt='V2',
  fabricacion=btrim(v_first->>'fabricacion'),longitud=(v_first->>'longitud')::numeric,
  reserva=v_res,acabado_pendiente=v_acab_res,validacion_estado='VALIDADO',
  validado_por=v_usuario,fecha_validacion=now(),
  observacion_validacion=nullif(btrim(coalesce(p_observacion,'')),'')
 WHERE id_pendiente=p_id;
 INSERT INTO public.sgp_aluminio_pendientes_historial
 (id_pendiente,usuario,observacion,estado_anterior,estado_nuevo,tipo_evento,datos_anteriores,datos_nuevos)
 VALUES(p_id,v_usuario,p_observacion,v_p.estado_repo,v_p.estado_repo,'VALIDACION_DETALLES_PDT',
  jsonb_build_object('cantidad_reportada',v_p.cantidad,'fabricacion_reportada',v_p.fabricacion),
  jsonb_build_object('cantidad_validada',v_total,'correccion',v_correction,'detalles',p_detalles));
 RETURN jsonb_build_object('ok',true,'cantidad_reportada',v_p.cantidad,'cantidad_validada',v_total,'detalles',v_count);
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_manual.validar(p_token text, p_id uuid, p_detalles jsonb, p_reserva text, p_observacion text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor text; original record; pending public.sgp_aluminio_pendientes%rowtype;
 row jsonb; src jsonb; sources jsonb; detail uuid; source_count integer; reference_total numeric;
 total bigint:=0; count_rows integer:=0; corrected boolean; first_row jsonb; seen text[]:=array[]::text[]; key text;
BEGIN
 actor:=public.sgp_pdt_validar_rol_real(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','RECEPCION','LIDER LINEA','SUPERVISOR DE PICKING']);
 SELECT * INTO STRICT pending FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
 SELECT md.*,r.key_produccion,r.produccion,r.reserva,r.acabado AS acabado_reporte
 INTO STRICT original FROM sgp_pdt_manual.detalles md JOIN sgp_pdt_manual.reportes r USING(id_reporte)
 WHERE md.id_pendiente=p_id;
 IF p_reserva IS DISTINCT FROM original.reserva OR pending.contrato_pdt<>'V2' OR pending.estado<>'PENDIENTE'
 OR pending.fecha_cierre IS NOT NULL OR pending.validacion_estado<>'POR_VALIDAR'
 OR coalesce(pending.estado_repo,'PENDIENTE')='PICKING'
 OR EXISTS(SELECT 1 FROM public.sgp_aluminio_pendiente_movimientos WHERE id_pendiente=p_id)
 OR EXISTS(SELECT 1 FROM public.sgp_aluminio_pendiente_detalles WHERE id_pendiente=p_id)
 THEN RAISE EXCEPTION 'PDT_MANUAL_NO_APTO_PARA_VALIDAR'; END IF;
 IF jsonb_typeof(p_detalles) IS DISTINCT FROM 'array' OR jsonb_array_length(p_detalles) NOT BETWEEN 1 AND 100
 THEN RAISE EXCEPTION 'PDT_MANUAL_DETALLES_INVALIDOS'; END IF;
 sources:=public.sgp_pdt_manual_fuentes_validacion_v1(p_token,p_id)->'fuentes';
 FOR row IN SELECT value FROM jsonb_array_elements(p_detalles) LOOP
  count_rows:=count_rows+1;
  IF nullif(btrim(row->>'fabricacion'),'') IS NULL OR nullif(btrim(row->>'acabado'),'') IS NULL
  OR row->>'longitud' !~ '^[0-9]+([.][0-9]+)?$' OR row->>'cantidad' !~ '^[0-9]+$'
  OR length(row->>'cantidad')>10 OR (row->>'cantidad')::numeric>2147483647
  OR (row->>'longitud')::numeric<=0 OR (row->>'cantidad')::integer<=0
  OR nullif(row->>'id_pieza','') IS NOT NULL
  THEN RAISE EXCEPTION 'PDT_MANUAL_DETALLE_INVALIDO'; END IF;
  IF row->>'perfil' IS NOT NULL AND row->>'perfil'<>original.perfil THEN RAISE EXCEPTION 'PDT_MANUAL_REFERENCIA_INMUTABLE'; END IF;
  IF upper(btrim(row->>'acabado'))<>upper(btrim(original.acabado_reporte)) THEN RAISE EXCEPTION 'PDT_MANUAL_ACABADO_AJENO'; END IF;
  key:=lower(btrim(row->>'fabricacion'))||'|'||(row->>'longitud')::numeric::text||'|'||upper(btrim(row->>'acabado'))||'|'||lower(btrim(coalesce(row->>'marca','')));
  IF key=ANY(seen) THEN RAISE EXCEPTION 'PDT_MANUAL_COMBINACION_REPETIDA'; END IF;
  seen:=array_append(seen,key);
  SELECT count(*),coalesce(sum(m.cantidad),0) INTO source_count,reference_total FROM (
   SELECT DISTINCT ON (x->>'id_pieza') x->>'id_pieza' id_pieza,(x->>'cantidad_referencia')::numeric cantidad
   FROM jsonb_array_elements(sources) x WHERE lower(btrim(x->>'fabricacion'))=lower(btrim(row->>'fabricacion'))
   AND (x->>'longitud')::numeric=(row->>'longitud')::numeric
   AND lower(btrim(coalesce(x->>'marca','')))=lower(btrim(coalesce(row->>'marca','')))
   AND upper(btrim(x->>'acabado'))=upper(btrim(row->>'acabado'))
  ) m;
  IF source_count<1 OR (row->>'cantidad')::integer>reference_total THEN RAISE EXCEPTION 'PDT_MANUAL_FUENTE_O_CANTIDAD_INVALIDA'; END IF;
  total:=total+(row->>'cantidad')::integer;
  IF total>2147483647 THEN RAISE EXCEPTION 'PDT_MANUAL_TOTAL_FUERA_DE_RANGO'; END IF;
  IF count_rows=1 THEN first_row:=row; END IF;
 END LOOP;
 corrected:=count_rows<>1 OR total<>original.cantidad
  OR lower(btrim(first_row->>'fabricacion'))<>lower(btrim(original.fabricacion))
  OR (first_row->>'longitud')::numeric<>original.longitud
  OR lower(btrim(coalesce(first_row->>'marca','')))<>lower(btrim(coalesce(original.marca,'')))
  OR upper(btrim(first_row->>'acabado'))<>upper(btrim(original.acabado));
 IF corrected AND nullif(btrim(coalesce(p_observacion,'')),'') IS NULL
 THEN RAISE EXCEPTION 'PDT_MANUAL_CORRECCION_REQUIERE_OBSERVACION'; END IF;
 FOR row IN SELECT value FROM jsonb_array_elements(p_detalles) LOOP
  INSERT INTO public.sgp_aluminio_pendiente_detalles(id_pendiente,id_pieza,fabricacion,longitud,acabado,cantidad_validada,creado_por)
  VALUES(p_id,'',btrim(row->>'fabricacion'),(row->>'longitud')::numeric,btrim(row->>'acabado'),(row->>'cantidad')::integer,actor)
  RETURNING id_detalle INTO detail;
  FOR src IN SELECT value FROM jsonb_array_elements(sources) x WHERE lower(btrim(x.value->>'fabricacion'))=lower(btrim(row->>'fabricacion'))
   AND (x.value->>'longitud')::numeric=(row->>'longitud')::numeric
   AND lower(btrim(coalesce(x.value->>'marca','')))=lower(btrim(coalesce(row->>'marca','')))
   AND upper(btrim(x.value->>'acabado'))=upper(btrim(row->>'acabado')) LOOP
   INSERT INTO sgp_pdt_manual.fuentes_validadas(id_detalle,id_pieza,snapshot)
   VALUES(detail,src->>'id_pieza',src) ON CONFLICT DO NOTHING;
  END LOOP;
 END LOOP;
 UPDATE public.sgp_aluminio_pendientes SET validacion_estado='VALIDADO',validado_por=actor,
  fecha_validacion=now(),observacion_validacion=nullif(btrim(p_observacion),''),
  fabricacion=btrim(first_row->>'fabricacion'),longitud=(first_row->>'longitud')::numeric
 WHERE id_pendiente=p_id;
 INSERT INTO public.sgp_aluminio_pendientes_historial
 (id_pendiente,usuario,observacion,estado_anterior,estado_nuevo,tipo_evento,datos_anteriores,datos_nuevos)
 VALUES(p_id,actor,p_observacion,pending.estado_repo,pending.estado_repo,'VALIDACION_MANUAL_PDT',
  jsonb_build_object('id_reporte',original.id_reporte,'perfil',original.perfil,'fabricacion',original.fabricacion,
   'marca',original.marca,'longitud',original.longitud,'acabado',original.acabado,'cantidad',original.cantidad,'nc',original.nc),
  jsonb_build_object('detalles',p_detalles,'cantidad_validada',total,'correccion',corrected));
 RETURN jsonb_build_object('ok',true,'cantidad_reportada',original.cantidad,'cantidad_validada',total,'detalles',count_rows,'correccion',corrected);
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_multiorigen.grouped_nuevo_entrega(p_token text, p_detalle uuid, p_entrega uuid, p_cantidad integer, p_clave uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d public.sgp_aluminio_pendiente_detalles%rowtype; p public.sgp_aluminio_pendientes%rowtype;
 e public.sgp_pdt_entrega_lineas%rowtype; u text; nuevo uuid; neto bigint;
BEGIN
 u:=public.sgp_validar_sesion_rol(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','PICKING','SUPERVISOR DE PICKING']);
 IF p_cantidad IS NULL OR p_cantidad<=0 OR p_clave IS NULL THEN RAISE EXCEPTION 'Cantidad/clave inválida'; END IF;
 SELECT * INTO STRICT d FROM public.sgp_aluminio_pendiente_detalles WHERE id_detalle=p_detalle;
 SELECT * INTO STRICT p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=d.id_pendiente FOR UPDATE;
 PERFORM public.sgp_pdt_exigir_panel_v3(p.id_pendiente);
 SELECT * INTO e FROM public.sgp_pdt_entrega_lineas WHERE clave=p_clave;
 IF FOUND THEN
  IF e.id_detalle<>p_detalle OR e.id_entrega<>p_entrega OR e.cantidad<>p_cantidad THEN RAISE EXCEPTION 'Clave reutilizada'; END IF;
  RETURN jsonb_build_object('ok',true,'duplicado',true,'id_linea',e.id_linea);
 END IF;
 IF p.contrato_pdt<>'V2' OR p.estado<>'PENDIENTE' OR p.validacion_estado<>'VALIDADO' THEN RAISE EXCEPTION 'PDT no apto'; END IF;
 PERFORM 1 FROM public.sgp_picking_entregas WHERE id_entrega=p_entrega FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Entrega inexistente'; END IF;
 PERFORM 1 FROM public.sgp_mecanizado_programacion mp JOIN public.sgp_picking_entregas pe_lock USING(id_programacion) WHERE pe_lock.id_entrega=p_entrega FOR UPDATE OF mp;
 -- Explicit event identity, not global order status or missing quantities.
 PERFORM 1 FROM public.sgp_picking_entregas pe
 JOIN public.sgp_mecanizado_programacion mp ON mp.id_programacion=pe.id_programacion
 JOIN public.sgp_producciones prod ON prod.key_produccion=p.key_produccion
 WHERE pe.id_entrega=p_entrega AND pe.produccion=prod.produccion
 AND upper(btrim(mp.sistema))=upper(btrim(prod.sistema))
 AND (mp.reserva=p.reserva OR (mp.reserva=p.reserva_principal AND EXISTS(SELECT 1 FROM public.sgp_produccion_reservas_v rel WHERE rel.key_produccion=p.key_produccion AND rel.reserva=p.reserva AND rel.reserva_principal=mp.reserva))) AND upper(btrim(mp.acabado))=upper(btrim(d.acabado))
 AND EXISTS(SELECT 1 FROM public.sgp_pdt_fuentes f WHERE f.id_detalle=d.id_detalle
 AND upper(btrim(f.snapshot->>'sistema'))=upper(btrim(mp.sistema))
 AND EXISTS(SELECT 1 FROM public.sgp_pdt_origenes_internal_v3(p.reserva,p.perfil,p.produccion,p.acabado_pendiente,f.id_pieza) x
 WHERE x->>'key_produccion'=p.key_produccion AND x->>'tipo_pieza'='PANEL' AND x->>'id_linea'='PANELES_2'
 AND f.snapshot->>'id_pieza'=x->>'id_pieza'
 AND (SELECT to_jsonb(a)-'cantidad' FROM public.sgp_aluminio a WHERE a.id_pieza=f.id_pieza)=f.snapshot-'cantidad'));
 IF NOT FOUND THEN RAISE EXCEPTION 'Entrega ajena o identidad incompleta'; END IF;
 SELECT coalesce(sum(CASE WHEN tipo='AVANCE' THEN cantidad ELSE -cantidad END),0) INTO neto
 FROM public.sgp_aluminio_pendiente_movimientos WHERE id_detalle=p_detalle;
 IF p_cantidad+coalesce((SELECT sum(cantidad) FROM public.sgp_pdt_entrega_lineas WHERE id_detalle=p_detalle AND estado<>'ANULADA'),0)>neto
 THEN RAISE EXCEPTION 'Entrega supera procesado'; END IF;
 INSERT INTO public.sgp_pdt_entrega_lineas(id_entrega,id_detalle,id_pieza,cantidad,clave,registrado_por)
 VALUES(p_entrega,p_detalle,'',p_cantidad,p_clave,u) RETURNING id_linea INTO nuevo;
 RETURN jsonb_build_object('ok',true,'id_linea',nuevo);
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_multiorigen.grouped_original_validar(p_token text, p_id uuid, p_detalles jsonb, p_reserva text DEFAULT NULL::text, p_observacion text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_usuario text; v_p public.sgp_aluminio_pendientes%rowtype;
 v_row jsonb; v_fab text; v_acab text; v_long numeric; v_cant integer;
 v_total bigint:=0; v_count integer:=0; v_first jsonb; v_source integer; v_detalle uuid; v_a public.sgp_aluminio%rowtype;
 v_key text; v_keys text[]:=array[]::text[]; v_out jsonb; v_correction boolean; v_res text; v_acab_res text;
BEGIN
 v_usuario:=public.sgp_validar_sesion_rol(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','LIDER LINEA','SUPERVISOR DE PICKING','RECEPCION']);
 SELECT * INTO v_p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
 IF NOT FOUND OR v_p.estado<>'PENDIENTE' OR v_p.fecha_cierre IS NOT NULL OR coalesce(v_p.estado_repo,'PENDIENTE')='PICKING' OR coalesce(v_p.validacion_estado,'POR_VALIDAR')='VALIDADO'
 THEN RAISE EXCEPTION 'Pendiente no activo o ya validado'; END IF;
 IF p_detalles IS NULL OR jsonb_typeof(p_detalles)<>'array' OR jsonb_array_length(p_detalles) NOT BETWEEN 1 AND 100
 THEN RAISE EXCEPTION 'Se requiere entre 1 y 100 fabricaciones'; END IF;
 IF EXISTS (SELECT 1 FROM public.sgp_aluminio_pendiente_movimientos WHERE id_pendiente=p_id)
 THEN RAISE EXCEPTION 'No se puede revalidar un pendiente con movimientos'; END IF;
 FOR v_row IN SELECT value FROM jsonb_array_elements(p_detalles)
 LOOP
  v_count:=v_count+1;
  v_fab:=nullif(btrim(v_row->>'fabricacion'),'');
  v_acab:=nullif(btrim(v_row->>'acabado'),'');
  IF v_row->>'longitud' !~ '^[0-9]+([.][0-9]+)?$'
    OR v_row->>'cantidad' !~ '^[0-9]+$'
  THEN RAISE EXCEPTION 'Longitud y cantidad deben ser numéricas'; END IF;
  v_long:=(v_row->>'longitud')::numeric;
  IF length(v_row->>'cantidad')>10 OR (v_row->>'cantidad')::numeric>2147483647 THEN RAISE EXCEPTION 'Cantidad fuera de rango'; END IF;
  v_cant:=(v_row->>'cantidad')::integer;
  IF v_fab IS NULL OR v_acab IS NULL OR v_long<=0 OR v_cant<=0
  THEN RAISE EXCEPTION 'Fabricación, acabado, longitud y cantidad obligatorios'; END IF;
  v_key:=lower(v_fab)||'|'||v_long::text||'|'||upper(v_acab);
  IF nullif(v_row->>'id_pieza','') IS NOT NULL THEN RAISE EXCEPTION 'Modo fuente mixta no permitido'; END IF;
  IF v_key=ANY(v_keys) THEN RAISE EXCEPTION 'Fabricación repetida'; END IF;
  v_keys:=array_append(v_keys,v_key);
  IF v_count=1 THEN v_first:=v_row; END IF;
  v_total:=v_total+v_cant;
  IF v_total>2147483647 THEN RAISE EXCEPTION 'Cantidad fuera de rango'; END IF;
 PERFORM public.sgp_pdt_exigir_panel_v3(p_id);
  IF nullif(btrim(v_p.key_produccion),'') IS NULL THEN RAISE EXCEPTION 'Identidad producción no resuelta'; END IF;
  SELECT count(*) INTO v_source FROM public.sgp_aluminio a
   JOIN public.sgp_producciones prod ON prod.key_produccion=a.key_produccion
   WHERE a.activo='SI' AND a.tipo_pieza='PANEL'
     AND a.key_produccion=v_p.key_produccion AND prod.id_linea='PANELES_2' AND btrim(a.produccion)=btrim(v_p.produccion)
     AND (nullif(btrim(coalesce(v_p.acabado_pendiente,'')),'') IS NULL OR upper(btrim(a.acabado))=upper(btrim(v_p.acabado_pendiente)))
     AND EXISTS(SELECT 1 FROM public.sgp_produccion_reservas_v r WHERE r.key_produccion=v_p.key_produccion AND r.reserva=coalesce(nullif(btrim(p_reserva),''),v_p.reserva) AND (r.acabado_reserva IS NULL OR upper(btrim(r.acabado_reserva))=upper(btrim(a.acabado))))
     AND upper(btrim(a.sistema))=upper(btrim(prod.sistema))
     AND btrim(a.codigo_sap)=btrim(v_p.perfil)
     AND lower(btrim(a.fabricacion))=lower(v_fab) AND a.longitud=v_long
     AND upper(btrim(a.acabado))=upper(v_acab);
  IF v_source<1 THEN RAISE EXCEPTION 'Fuente PANEL inexistente o ambigua'; END IF;
 END LOOP;
 v_correction := v_total IS DISTINCT FROM v_p.cantidad;
 IF v_correction AND nullif(btrim(coalesce(p_observacion,'')),'') IS NULL
 THEN RAISE EXCEPTION 'Corrección de cantidad requiere observación'; END IF;
 -- Dedicated validation for this new RPC. Legacy validator is not modified.
 v_res:=coalesce(nullif(btrim(coalesce(p_reserva,'')),''),v_p.reserva);
 v_acab_res:=coalesce(nullif(btrim(coalesce(v_p.acabado_pendiente,'')),''),nullif(btrim(v_first->>'acabado'),''));
 IF v_res IS NULL OR v_acab_res IS NULL THEN RAISE EXCEPTION 'Reserva y acabado obligatorios'; END IF;
 IF nullif(btrim(coalesce(v_p.key_produccion,'')),'') IS NOT NULL
 AND NOT EXISTS (SELECT 1 FROM public.sgp_produccion_reservas_v r
  WHERE r.key_produccion=v_p.key_produccion AND r.reserva=v_res
    AND (r.acabado_reserva IS NULL OR upper(btrim(r.acabado_reserva))=upper(v_acab_res)))
 THEN RAISE EXCEPTION 'Reserva/acabado no pertenece a producción'; END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_detalles) d
  WHERE upper(btrim(d->>'acabado'))<>upper(v_acab_res))
 THEN RAISE EXCEPTION 'Acabado distinto al de la reserva'; END IF;
 INSERT INTO public.sgp_aluminio_pendientes_historial
 (id_pendiente,estado_nuevo,usuario,observacion,tipo_evento,datos_anteriores,datos_nuevos)
 VALUES(p_id,coalesce(v_p.estado_repo,'PENDIENTE'),v_usuario,p_observacion,'VALIDACION_PDT',
  jsonb_build_object('fabricacion',v_p.fabricacion,'longitud',v_p.longitud,
   'reserva',v_p.reserva,'acabado',v_p.acabado_pendiente,'validacion_estado',v_p.validacion_estado),
  jsonb_build_object('fabricacion',v_first->>'fabricacion','reserva',v_res,
   'acabado',v_acab_res,'validacion_estado','VALIDADO'));
 FOR v_row IN SELECT value FROM jsonb_array_elements(p_detalles)
 LOOP
  v_fab:=btrim(v_row->>'fabricacion'); v_long:=(v_row->>'longitud')::numeric; v_acab:=btrim(v_row->>'acabado');
  INSERT INTO public.sgp_aluminio_pendiente_detalles
   (id_pendiente,id_pieza,fabricacion,longitud,acabado,cantidad_validada,creado_por)
  VALUES (p_id,'',v_fab,v_long,v_acab,(v_row->>'cantidad')::integer,v_usuario) RETURNING id_detalle INTO v_detalle;
  FOR v_a IN SELECT DISTINCT a.* FROM public.sgp_aluminio a
   JOIN public.sgp_producciones prod ON prod.key_produccion=a.key_produccion
   WHERE a.activo='SI' AND a.tipo_pieza='PANEL'
     AND a.key_produccion=v_p.key_produccion AND prod.id_linea='PANELES_2' AND btrim(a.produccion)=btrim(v_p.produccion)
     AND (nullif(btrim(coalesce(v_p.acabado_pendiente,'')),'') IS NULL OR upper(btrim(a.acabado))=upper(btrim(v_p.acabado_pendiente)))
     AND EXISTS(SELECT 1 FROM public.sgp_produccion_reservas_v r WHERE r.key_produccion=v_p.key_produccion AND r.reserva=coalesce(nullif(btrim(p_reserva),''),v_p.reserva) AND (r.acabado_reserva IS NULL OR upper(btrim(r.acabado_reserva))=upper(btrim(a.acabado))))
     AND upper(btrim(a.sistema))=upper(btrim(prod.sistema))
     AND btrim(a.codigo_sap)=btrim(v_p.perfil)
     AND lower(btrim(a.fabricacion))=lower(v_fab) AND a.longitud=v_long
     AND upper(btrim(a.acabado))=upper(v_acab) LOOP
   INSERT INTO public.sgp_pdt_fuentes(id_detalle,id_pieza,id_carga,fila_origen,snapshot)
   VALUES(v_detalle,v_a.id_pieza,v_a.id_carga,v_a.fila_origen,to_jsonb(v_a));
  END LOOP;
  IF NOT FOUND THEN RAISE EXCEPTION 'Fuentes PANEL cambiaron durante validación'; END IF;
 END LOOP;
 UPDATE public.sgp_aluminio_pendientes SET contrato_pdt='V2',
  fabricacion=btrim(v_first->>'fabricacion'),longitud=(v_first->>'longitud')::numeric,
  reserva=v_res,acabado_pendiente=v_acab_res,validacion_estado='VALIDADO',
  validado_por=v_usuario,fecha_validacion=now(),
  observacion_validacion=nullif(btrim(coalesce(p_observacion,'')),'')
 WHERE id_pendiente=p_id;
 INSERT INTO public.sgp_aluminio_pendientes_historial
 (id_pendiente,estado_nuevo,usuario,observacion,tipo_evento,datos_anteriores,datos_nuevos)
 VALUES(p_id,coalesce(v_p.estado_repo,'PENDIENTE'),v_usuario,p_observacion,'VALIDACION_DETALLES_PDT',
  jsonb_build_object('cantidad_reportada',v_p.cantidad,'fabricacion_reportada',v_p.fabricacion),
  jsonb_build_object('cantidad_validada',v_total,'correccion',v_correction,'detalles',p_detalles));
 RETURN jsonb_build_object('ok',true,'cantidad_reportada',v_p.cantidad,'cantidad_validada',v_total,'detalles',v_count);
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_multiorigen.grouped_original_entrega(p_token text, p_detalle uuid, p_entrega uuid, p_cantidad integer, p_clave uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d public.sgp_aluminio_pendiente_detalles%rowtype; p public.sgp_aluminio_pendientes%rowtype;
 e public.sgp_pdt_entrega_lineas%rowtype; u text; nuevo uuid; neto bigint;
BEGIN
 u:=public.sgp_validar_sesion_rol(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','PICKING','SUPERVISOR DE PICKING']);
 IF p_cantidad IS NULL OR p_cantidad<=0 OR p_clave IS NULL THEN RAISE EXCEPTION 'Cantidad/clave inválida'; END IF;
 SELECT * INTO STRICT d FROM public.sgp_aluminio_pendiente_detalles WHERE id_detalle=p_detalle;
 SELECT * INTO STRICT p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=d.id_pendiente FOR UPDATE;
 PERFORM public.sgp_pdt_exigir_panel_v3(p.id_pendiente);
 SELECT * INTO e FROM public.sgp_pdt_entrega_lineas WHERE clave=p_clave;
 IF FOUND THEN
  IF e.id_detalle<>p_detalle OR e.id_entrega<>p_entrega OR e.cantidad<>p_cantidad THEN RAISE EXCEPTION 'Clave reutilizada'; END IF;
  RETURN jsonb_build_object('ok',true,'duplicado',true,'id_linea',e.id_linea);
 END IF;
 IF p.contrato_pdt<>'V2' OR p.estado<>'PENDIENTE' OR p.validacion_estado<>'VALIDADO' THEN RAISE EXCEPTION 'PDT no apto'; END IF;
 PERFORM 1 FROM public.sgp_picking_entregas WHERE id_entrega=p_entrega FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Entrega inexistente'; END IF;
 PERFORM 1 FROM public.sgp_mecanizado_programacion mp JOIN public.sgp_picking_entregas pe_lock USING(id_programacion) WHERE pe_lock.id_entrega=p_entrega FOR UPDATE OF mp;
 -- Explicit event identity, not global order status or missing quantities.
 PERFORM 1 FROM public.sgp_picking_entregas pe
 JOIN public.sgp_mecanizado_programacion mp ON mp.id_programacion=pe.id_programacion
 JOIN public.sgp_producciones prod ON prod.key_produccion=p.key_produccion
 WHERE pe.id_entrega=p_entrega AND pe.produccion=prod.produccion
 AND upper(btrim(mp.sistema))=upper(btrim(prod.sistema))
 AND mp.reserva=p.reserva AND upper(btrim(mp.acabado))=upper(btrim(d.acabado))
 AND EXISTS(SELECT 1 FROM public.sgp_pdt_fuentes f WHERE f.id_detalle=d.id_detalle
 AND upper(btrim(f.snapshot->>'sistema'))=upper(btrim(mp.sistema))
 AND f.snapshot->>'key_produccion'=p.key_produccion);
 IF NOT FOUND THEN RAISE EXCEPTION 'Entrega ajena o identidad incompleta'; END IF;
 SELECT coalesce(sum(CASE WHEN tipo='AVANCE' THEN cantidad ELSE -cantidad END),0) INTO neto
 FROM public.sgp_aluminio_pendiente_movimientos WHERE id_detalle=p_detalle;
 IF p_cantidad+coalesce((SELECT sum(cantidad) FROM public.sgp_pdt_entrega_lineas WHERE id_detalle=p_detalle AND estado<>'ANULADA'),0)>neto
 THEN RAISE EXCEPTION 'Entrega supera procesado'; END IF;
 INSERT INTO public.sgp_pdt_entrega_lineas(id_entrega,id_detalle,id_pieza,cantidad,clave,registrado_por)
 VALUES(p_entrega,p_detalle,'',p_cantidad,p_clave,u) RETURNING id_linea INTO nuevo;
 RETURN jsonb_build_object('ok',true,'id_linea',nuevo);
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_manual.original_estado_v2(p_token text, p_id uuid, p_estado text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p public.sgp_aluminio_pendientes%rowtype; u text;
BEGIN
 u:=public.sgp_pdt_validar_rol_real(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','LIDER MECANIZADO','LIDER']);
 SELECT * INTO STRICT p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
 IF p.contrato_pdt<>'V2' OR p.estado<>'PENDIENTE' THEN RAISE EXCEPTION 'PDT no activo V2'; END IF;
 IF p_estado IS NULL OR p_estado NOT IN ('CORTE','MECANIZADO','PROCESADO') THEN RAISE EXCEPTION 'Etapa inválida'; END IF;
 IF p.estado_repo=p_estado THEN RETURN jsonb_build_object('ok',true,'duplicado',true,'estado_repo',p_estado); END IF;
 UPDATE public.sgp_aluminio_pendientes SET estado_repo=p_estado,usuario_estado=u,fecha_estado=now() WHERE id_pendiente=p_id;
 INSERT INTO public.sgp_aluminio_pendientes_historial(id_pendiente,usuario,tipo_evento,estado_anterior,estado_nuevo,datos_anteriores,datos_nuevos)
 VALUES(p_id,u,'ETAPA_V2',p.estado_repo,p_estado,jsonb_build_object('estado',p.estado_repo),jsonb_build_object('estado',p_estado));
 RETURN jsonb_build_object('ok',true,'estado_repo',p_estado);
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_manual.original_cierre_acreditado(p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM public.sgp_aluminio_pendiente_detalles WHERE id_pendiente=p_id AND id_pieza='') THEN
  IF sgp_pdt_multiorigen.es_registro_v4(p_id) THEN RETURN sgp_pdt_multiorigen.grouped_nuevo_cierre_acreditado(p_id); END IF;
  RETURN sgp_pdt_multiorigen.grouped_original_cierre_acreditado(p_id);
 END IF;
 IF sgp_pdt_multiorigen.es_registro_v4(p_id) THEN RETURN sgp_pdt_multiorigen.nuevo_sgp_pdt_cierre_acreditado(p_id); END IF;
 RETURN sgp_pdt_multiorigen.original_sgp_pdt_cierre_acreditado(p_id);
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_manual.original_validar(p_token text, p_id uuid, p_detalles jsonb, p_reserva text DEFAULT NULL::text, p_observacion text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF jsonb_typeof(p_detalles)='array' AND jsonb_array_length(p_detalles)>0
 AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_detalles) x WHERE nullif(x->>'id_pieza','') IS NOT NULL) THEN
  IF sgp_pdt_multiorigen.es_registro_v4(p_id) THEN
   RETURN sgp_pdt_multiorigen.grouped_nuevo_validar(p_token,p_id,p_detalles,p_reserva,p_observacion);
  END IF;
  RETURN sgp_pdt_multiorigen.grouped_original_validar(p_token,p_id,p_detalles,p_reserva,p_observacion);
 END IF;
 IF sgp_pdt_multiorigen.es_registro_v4(p_id) THEN
  RETURN sgp_pdt_multiorigen.nuevo_sgp_aluminio_pendiente_validar_detalles_v1(p_token,p_id,p_detalles,p_reserva,p_observacion);
 END IF;
 RETURN sgp_pdt_multiorigen.original_sgp_aluminio_pendiente_validar_detalles_v1(p_token,p_id,p_detalles,p_reserva,p_observacion);
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_manual.original_avance(p_token text, p_id uuid, p_id_detalle uuid, p_cantidad integer, p_turno text, p_fecha_operativa date, p_idempotency_key uuid, p_observacion text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_usuario text; v_p public.sgp_aluminio_pendientes%rowtype;
 v_d public.sgp_aluminio_pendiente_detalles%rowtype;
 v_solved bigint; v_remaining bigint; v_existing public.sgp_aluminio_pendiente_movimientos%rowtype;
BEGIN
 v_usuario:=public.sgp_pdt_validar_rol_real(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','LIDER MECANIZADO','LIDER']);
 IF p_id IS NULL OR p_id_detalle IS NULL OR p_cantidad IS NULL OR p_cantidad<=0 OR p_turno IS NULL OR p_turno NOT IN ('T1','T2')
 OR p_fecha_operativa IS NULL OR p_idempotency_key IS NULL
 THEN RAISE EXCEPTION 'Parámetros de avance inválidos'; END IF;
 SELECT * INTO v_p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Pendiente inexistente'; END IF;
 SELECT * INTO v_existing FROM public.sgp_aluminio_pendiente_movimientos
 WHERE idempotency_key=p_idempotency_key;
 IF FOUND THEN
  IF v_existing.id_pendiente<>p_id OR v_existing.id_detalle<>p_id_detalle
    OR v_existing.cantidad<>p_cantidad OR v_existing.tipo<>'AVANCE'
    OR v_existing.turno<>p_turno OR v_existing.fecha_operativa<>p_fecha_operativa
    OR v_existing.observacion IS DISTINCT FROM p_observacion
  THEN RAISE EXCEPTION 'Clave de idempotencia reutilizada'; END IF;
  RETURN jsonb_build_object('ok',true,'duplicado',true,'id_movimiento',v_existing.id_movimiento);
 END IF;
 IF v_p.contrato_pdt<>'V2' OR v_p.estado<>'PENDIENTE' OR v_p.validacion_estado<>'VALIDADO'
 OR v_p.estado_repo='PICKING' OR v_p.fecha_cierre IS NOT NULL THEN RAISE EXCEPTION 'Pendiente no apto para avances'; END IF;
 SELECT * INTO v_d FROM public.sgp_aluminio_pendiente_detalles
 WHERE id_detalle=p_id_detalle AND id_pendiente=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Fabricación no pertenece al pendiente'; END IF;
 SELECT coalesce(sum(CASE WHEN m.tipo='AVANCE' THEN m.cantidad ELSE -m.cantidad END),0)
 INTO v_solved FROM public.sgp_aluminio_pendiente_movimientos m
 WHERE m.id_detalle=p_id_detalle;
 v_remaining:=v_d.cantidad_validada-v_solved;
 IF p_cantidad>v_remaining THEN RAISE EXCEPTION 'Cantidad supera saldo de fabricación'; END IF;
 INSERT INTO public.sgp_aluminio_pendiente_movimientos
 (id_pendiente,id_detalle,tipo,cantidad,idempotency_key,usuario,turno,fecha_operativa,observacion)
 VALUES(p_id,p_id_detalle,'AVANCE',p_cantidad,p_idempotency_key,v_usuario,p_turno,p_fecha_operativa,p_observacion);
 INSERT INTO public.sgp_aluminio_pendientes_historial
 (id_pendiente,usuario,observacion,tipo_evento,estado_anterior,estado_nuevo,datos_nuevos)
 VALUES(p_id,v_usuario,p_observacion,'AVANCE_PDT',v_p.estado_repo,v_p.estado_repo,
 jsonb_build_object('id_detalle',p_id_detalle,'cantidad',p_cantidad,'turno',p_turno,
 'fecha_operativa',p_fecha_operativa,'saldo_detalle',v_remaining-p_cantidad));
 RETURN jsonb_build_object('ok',true,'duplicado',false,'saldo_detalle',v_remaining-p_cantidad);
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_manual.proteger_entrega_origen()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM sgp_pdt_manual.entregas WHERE id_entrega=OLD.id_entrega AND estado='VALIDADA') THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PDT_MANUAL_ENTREGA_ACREDITADA'; END IF;
  IF ROW(NEW.produccion,NEW.id_programacion,NEW.estado) IS DISTINCT FROM
     ROW(OLD.produccion,OLD.id_programacion,OLD.estado)
  THEN RAISE EXCEPTION 'PDT_MANUAL_CONCILIAR_ENTREGA_ANTES_DE_CAMBIO'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_manual.proteger_programacion_origen()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM sgp_pdt_manual.entregas l JOIN public.sgp_picking_entregas e USING(id_entrega)
  WHERE e.id_programacion=OLD.id_programacion AND l.estado='VALIDADA') THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PDT_MANUAL_PROGRAMACION_ACREDITADA'; END IF;
  IF ROW(NEW.reserva,NEW.sistema,NEW.acabado) IS DISTINCT FROM ROW(OLD.reserva,OLD.sistema,OLD.acabado)
  THEN RAISE EXCEPTION 'PDT_MANUAL_CONCILIAR_PROGRAMACION_ANTES_DE_CAMBIO'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_manual.original_cerrar_v2(p_token text, p_id uuid, p_clave uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p public.sgp_aluminio_pendientes%rowtype; u text; e public.sgp_pdt_cierres%rowtype;
BEGIN
 u:=public.sgp_validar_sesion_rol(p_token,ARRAY['COORDINADOR','PICKING','SUPERVISOR DE PICKING','ADMINISTRADOR']);
 IF p_clave IS NULL THEN RAISE EXCEPTION 'Clave requerida'; END IF;
 SELECT * INTO STRICT p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
 SELECT * INTO e FROM public.sgp_pdt_cierres WHERE id_pendiente=p_id;
 IF FOUND THEN
  IF e.clave<>p_clave THEN RAISE EXCEPTION 'Cierre ya registrado'; END IF;
  RETURN jsonb_build_object('ok',true,'duplicado',true);
 END IF;
 IF p.contrato_pdt<>'V2' OR p.estado<>'PENDIENTE' OR p.validacion_estado<>'VALIDADO' OR p.estado_repo<>'PROCESADO' THEN RAISE EXCEPTION 'PDT no apto para cierre'; END IF;
 PERFORM 1 FROM public.sgp_picking_entregas pe WHERE pe.id_entrega IN (
 SELECT l.id_entrega FROM public.sgp_pdt_entrega_lineas l JOIN public.sgp_aluminio_pendiente_detalles d USING(id_detalle)
 WHERE d.id_pendiente=p_id) ORDER BY pe.id_entrega FOR UPDATE;
 INSERT INTO public.sgp_pdt_cierres(id_pendiente,clave,usuario,evidencia)
 VALUES(p_id,p_clave,u,(SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]'::jsonb) FROM public.sgp_pdt_asignaciones a
 JOIN public.sgp_aluminio_pendiente_detalles d USING(id_detalle) WHERE d.id_pendiente=p_id));
 IF NOT public.sgp_pdt_cierre_acreditado(p_id) THEN RAISE EXCEPTION 'Cobertura Picking incompleta'; END IF;
 UPDATE public.sgp_aluminio_pendientes SET estado='RESUELTO',estado_repo='PICKING',usuario_cierre=u,fecha_cierre=now() WHERE id_pendiente=p_id;
 INSERT INTO public.sgp_aluminio_pendientes_historial(id_pendiente,usuario,estado_anterior,estado_nuevo,tipo_evento,datos_nuevos)
 VALUES(p_id,u,p.estado_repo,'PICKING','CIERRE_V2',jsonb_build_object('clave',p_clave));
 RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_manual.auditar_programacion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE before_week integer; after_week integer; current_year integer; item record; inserted uuid;
BEGIN
 before_week:=coalesce(OLD.semana_actual,OLD.semana_base);
 -- Deferred execution observes the final row after Export updates week and year.
 SELECT p.anio,coalesce(p.semana_actual,p.semana_base) INTO STRICT current_year,after_week
 FROM public.sgp_producciones p WHERE p.key_produccion=NEW.key_produccion;
 IF ROW(OLD.anio,before_week) IS NOT DISTINCT FROM ROW(current_year,after_week) THEN RETURN NEW; END IF;
 IF OLD.anio NOT BETWEEN 2020 AND 2100 OR current_year NOT BETWEEN 2020 AND 2100
 OR before_week NOT BETWEEN 1 AND 53 OR after_week NOT BETWEEN 1 AND 53
 THEN RAISE EXCEPTION 'PDT_MANUAL_PERIODO_INVALIDO'; END IF;
 FOR item IN SELECT DISTINCT md.id_pendiente FROM sgp_pdt_manual.reportes r
  JOIN sgp_pdt_manual.detalles md USING(id_reporte)
  WHERE r.key_produccion=NEW.key_produccion LOOP
  inserted:=NULL;
  INSERT INTO sgp_pdt_manual.programacion_cambios
   (id_pendiente,key_produccion,anio_anterior,semana_anterior,anio_nuevo,semana_nueva)
  VALUES(item.id_pendiente,NEW.key_produccion,OLD.anio,before_week,current_year,after_week)
  ON CONFLICT(id_pendiente,transaccion) DO NOTHING RETURNING id_cambio INTO inserted;
  IF inserted IS NULL THEN CONTINUE; END IF;
  INSERT INTO public.sgp_aluminio_pendientes_historial
   (id_pendiente,usuario,tipo_evento,observacion,estado_anterior,estado_nuevo,datos_anteriores,datos_nuevos)
  VALUES(item.id_pendiente,current_user,'REPROGRAMACION_PDT_MANUAL',
   'Cambio de programación; el reporte original permanece inmutable',
   (SELECT estado_repo FROM public.sgp_aluminio_pendientes WHERE id_pendiente=item.id_pendiente),
   (SELECT estado_repo FROM public.sgp_aluminio_pendientes WHERE id_pendiente=item.id_pendiente),
   jsonb_build_object('anio',OLD.anio,'semana',before_week,'key_produccion',OLD.key_produccion),
   jsonb_build_object('anio',current_year,'semana',after_week,'key_produccion',NEW.key_produccion));
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_manual_fuentes_v1(p_token text, p_key_produccion text, p_reserva text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE data jsonb;
BEGIN
 PERFORM public.sgp_pdt_validar_rol_real(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','LIDER LINEA']);
 IF (SELECT count(*) FROM sgp_pdt_manual.programacion(p_key_produccion,p_reserva) p WHERE p.anio IS NOT NULL AND p.semana BETWEEN 1 AND 53)<>1
 THEN RAISE EXCEPTION 'PDT_MANUAL_PROGRAMACION_AMBIGUA'; END IF;
 SELECT coalesce(jsonb_agg(x ORDER BY x->>'codigo_sap',x->>'fabricacion',x->>'longitud',x->>'id_pieza'),'[]'::jsonb) INTO data
 FROM (SELECT DISTINCT x FROM public.sgp_pdt_origenes_internal_v3(p_reserva,NULL,
  (SELECT p.produccion FROM sgp_pdt_manual.programacion(p_key_produccion,p_reserva) p LIMIT 1),NULL,NULL) x
  WHERE x->>'key_produccion'=p_key_produccion AND x->>'reserva'=p_reserva
  AND x->>'tipo_pieza'='PANEL' AND x->>'id_linea'='PANELES_2' LIMIT 1001) q;
 IF jsonb_array_length(data)>1000 THEN RAISE EXCEPTION 'PDT_MANUAL_FUENTES_EXCEDEN_LIMITE'; END IF;
 RETURN jsonb_build_object('ok',true,'fuentes',data);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_picking_piezas(p_token text, p_id_programacion uuid, p_produccion text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u text; v_reserva text; v_parte text; v_prod_num text;
begin
 u:=sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR','LIDER MECANIZADO','LIDER','PATINADOR','PICKING','SUPERVISOR DE PICKING','LIDER LINEA']);
 select reserva,prioridad_semanal into v_reserva,v_parte from sgp_mecanizado_programacion where id_programacion=p_id_programacion;
 v_prod_num:=nullif(substring(coalesce(p_produccion,'') from '^[[:space:]]*([0-9]+)'),'');
 return coalesce((select jsonb_agg(jsonb_build_object(
  'id_pieza',a.id_pieza,'produccion',a.produccion,'codigo_sap',a.codigo_sap,'perfil',a.codigo_sap,'descripcion',a.descripcion,'marca',a.marca,'fabricacion',a.fabricacion,'longitud',a.longitud,'cantidad',a.cantidad,'sistema',a.sistema,'acabado',a.acabado,'tipo_pieza',a.tipo_pieza
 ) order by a.produccion,a.codigo_sap,a.fabricacion,a.longitud)
 from sgp_aluminio a
 where a.activo='SI'
 and (
   (v_reserva is not null and a.key_produccion in (select pr.key_produccion from sgp_prioridades pr where pr.reserva=v_reserva and (v_parte is null or v_parte='' or pr.prioridad=v_parte) and pr.id_linea='PANELES_2')
    and (p_produccion is null or a.produccion=p_produccion or a.id_orden_produccion::text=p_produccion))
   or
   (p_produccion is not null and a.produccion=p_produccion)
   or
   (v_prod_num is not null and (a.id_orden_produccion::text=v_prod_num or substring(coalesce(a.produccion,'') from '^[[:space:]]*([0-9]+)')=v_prod_num))
 )
 ),'[]'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.sgp_picking_piezas_panel(p_token text, p_id_programacion uuid, p_produccion text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_sistema text;
  v_acabado text;
  v_reserva text;
  v_multi boolean:=false;
begin
  select sistema,acabado,reserva into v_sistema,v_acabado,v_reserva
  from public.sgp_mecanizado_programacion
  where id_programacion=p_id_programacion;

  if p_produccion is not null then
    select coalesce(count(distinct v.reserva)>1,false) into v_multi
    from public.sgp_produccion_reservas_v v
    where v.produccion=p_produccion and v.reserva_principal=v_reserva;
  else
    select exists(
      select 1
      from public.sgp_prioridades pr
      join public.sgp_produccion_reservas_v v on v.key_produccion=pr.key_produccion
      join public.sgp_mecanizado_programacion mp on mp.id_programacion=p_id_programacion
      where pr.reserva=mp.reserva and pr.id_linea='PANELES_2'
        and (mp.prioridad_semanal is null or pr.prioridad=mp.prioridad_semanal)
      group by v.key_produccion
      having count(distinct v.reserva)>1
    ) into v_multi;
  end if;

  return coalesce((
    select jsonb_agg(x)
    from jsonb_array_elements(
      public.sgp_picking_piezas(p_token,p_id_programacion,p_produccion)
    ) x
    join public.sgp_maestro_piezas m
      on trim(m.codigo_sap)=trim(coalesce(x->>'codigo_sap',x->>'perfil'))
     and m.activo='SI'
     and m.tipo_pieza='PANEL'
    where (v_sistema is null or trim(v_sistema)='' or upper(trim(coalesce(x->>'sistema','')))=upper(trim(v_sistema)))
      and (
        v_multi
        or v_acabado is null
        or trim(v_acabado)=''
        or upper(trim(coalesce(x->>'acabado','')))=upper(trim(v_acabado))
      )
  ),'[]'::jsonb);
end
$function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_guardar_contrato()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE has_details boolean;
BEGIN
 IF TG_OP='DELETE' AND OLD.contrato_pdt='LEGACY' THEN RETURN OLD; END IF;
 IF TG_OP='UPDATE' AND OLD.contrato_pdt='V2' AND NEW.contrato_pdt<>'V2' THEN RAISE EXCEPTION 'PDT_NO_DEGRADABLE'; END IF;
 IF TG_OP='UPDATE' AND OLD.contrato_pdt='LEGACY' AND NEW.contrato_pdt='V2' THEN
  IF OLD.validacion_estado='VALIDADO' OR NEW.validacion_estado<>'VALIDADO' OR NOT EXISTS(
   SELECT 1 FROM public.sgp_aluminio_pendiente_detalles d JOIN public.sgp_pdt_fuentes f USING(id_detalle)
   WHERE d.id_pendiente=OLD.id_pendiente) THEN RAISE EXCEPTION 'PDT_CONVERSION_NO_CONCILIADA'; END IF;
 END IF;
 IF TG_OP<>'DELETE' AND NEW.contrato_pdt='LEGACY' THEN RETURN NEW; END IF;
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'PDT_DELETE_REQUIERE_CONCILIACION';
 END IF;
 IF (TG_OP='INSERT' AND (NEW.estado='RESUELTO' OR NEW.estado_repo='PICKING' OR NEW.fecha_cierre IS NOT NULL)) THEN
  RAISE EXCEPTION 'PDT_CIERRE_SIN_EVIDENCIA_CUANTITATIVA';
 END IF;
 IF TG_OP='UPDATE' THEN
  IF (NEW.estado='RESUELTO' AND OLD.estado IS DISTINCT FROM NEW.estado)
   OR (NEW.estado_repo='PICKING' AND OLD.estado_repo IS DISTINCT FROM NEW.estado_repo)
   OR (NEW.fecha_cierre IS NOT NULL AND OLD.fecha_cierre IS DISTINCT FROM NEW.fecha_cierre) THEN
   IF NOT public.sgp_pdt_cierre_acreditado(NEW.id_pendiente) THEN RAISE EXCEPTION 'PDT_CIERRE_SIN_EVIDENCIA_CUANTITATIVA'; END IF;
  END IF;
  IF OLD.estado='RESUELTO' OR OLD.fecha_cierre IS NOT NULL OR OLD.estado_repo='PICKING' THEN
   IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'PDT_CERRADO_INMUTABLE'; END IF;
  END IF;
  IF NEW.cantidad IS DISTINCT FROM OLD.cantidad THEN
   RAISE EXCEPTION 'PDT_CANTIDAD_REPORTADA_INMUTABLE';
  END IF;
  SELECT EXISTS(SELECT 1 FROM public.sgp_aluminio_pendiente_detalles d
   WHERE d.id_pendiente=OLD.id_pendiente) INTO has_details;
  IF OLD.validacion_estado='VALIDADO' AND (
   NEW.validacion_estado IS DISTINCT FROM OLD.validacion_estado OR
   ROW(NEW.fabricacion,NEW.longitud,NEW.reserva,NEW.acabado_pendiente,NEW.perfil,NEW.key_produccion,NEW.produccion,NEW.id_pieza)
   IS DISTINCT FROM ROW(OLD.fabricacion,OLD.longitud,OLD.reserva,OLD.acabado_pendiente,OLD.perfil,OLD.key_produccion,OLD.produccion,OLD.id_pieza)) THEN
   RAISE EXCEPTION 'PDT_DISTRIBUCION_VALIDADA_INMUTABLE';
  END IF;
  IF has_details AND NEW.estado_repo IS DISTINCT FROM OLD.estado_repo THEN
   IF NOT coalesce((OLD.estado_repo='PENDIENTE' AND NEW.estado_repo='CORTE') OR
    (OLD.estado_repo='CORTE' AND NEW.estado_repo='MECANIZADO') OR
    (OLD.estado_repo='MECANIZADO' AND NEW.estado_repo='PROCESADO') OR
    (OLD.estado_repo='PROCESADO' AND NEW.estado_repo='MECANIZADO' AND EXISTS(SELECT 1 FROM public.sgp_aluminio_pendiente_movimientos m WHERE m.id_pendiente=OLD.id_pendiente AND m.tipo='REVERSO')) OR
    (OLD.estado_repo='PROCESADO' AND NEW.estado_repo='PICKING' AND public.sgp_pdt_cierre_acreditado(NEW.id_pendiente)),false) THEN
    RAISE EXCEPTION 'PDT_TRANSICION_NO_PERMITIDA';
   END IF;
   IF NEW.estado_repo='PROCESADO' AND EXISTS(
    SELECT 1 FROM public.sgp_aluminio_pendiente_detalles d
    WHERE d.id_pendiente=OLD.id_pendiente AND d.cantidad_validada<>(
     SELECT coalesce(sum(CASE WHEN m.tipo='AVANCE' THEN m.cantidad ELSE -m.cantidad END),0)
     FROM public.sgp_aluminio_pendiente_movimientos m WHERE m.id_detalle=d.id_detalle)) THEN
    RAISE EXCEPTION 'PDT_MECANIZADO_CON_SALDO';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_proteger_entrega_origen()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM public.sgp_pdt_entrega_lineas WHERE id_entrega=OLD.id_entrega AND estado<>'ANULADA') THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Entrega con evidencia PDT vigente'; END IF;
  IF ROW(NEW.produccion,NEW.id_programacion) IS DISTINCT FROM ROW(OLD.produccion,OLD.id_programacion) THEN
   RAISE EXCEPTION 'Conciliar evidencia PDT antes de modificar entrega';
  END IF;
  -- Registered quantities do not certify delivery: let the legacy audit produce
  -- VALIDADA or AUDITADA_DIFERENCIA. Once certified, annul explicitly first.
  IF NEW.estado IS DISTINCT FROM OLD.estado AND EXISTS(
   SELECT 1 FROM public.sgp_pdt_entrega_lineas WHERE id_entrega=OLD.id_entrega AND estado='VALIDADA') THEN
   RAISE EXCEPTION 'Conciliar evidencia PDT antes de modificar entrega';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_proteger_programacion_origen()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM public.sgp_pdt_entrega_lineas l JOIN public.sgp_picking_entregas e USING(id_entrega)
 WHERE e.id_programacion=OLD.id_programacion AND l.estado<>'ANULADA') THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Programación con evidencia PDT vigente'; END IF;
  IF ROW(NEW.sistema,NEW.reserva,NEW.acabado) IS DISTINCT FROM ROW(OLD.sistema,OLD.reserva,OLD.acabado)
  THEN RAISE EXCEPTION 'Conciliar evidencia PDT antes de modificar identidad de programación'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_entrega_validar_v2(p_token text, p_linea uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE l public.sgp_pdt_entrega_lineas%rowtype; parent uuid; u text; p public.sgp_aluminio_pendientes%rowtype;
BEGIN
 u:=public.sgp_validar_sesion_rol(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','RECEPCION','SUPERVISOR DE PICKING']);
 SELECT d.id_pendiente INTO STRICT parent FROM public.sgp_pdt_entrega_lineas x JOIN public.sgp_aluminio_pendiente_detalles d USING(id_detalle) WHERE x.id_linea=p_linea;
 SELECT * INTO STRICT p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=parent FOR UPDATE;
 SELECT * INTO STRICT l FROM public.sgp_pdt_entrega_lineas WHERE id_linea=p_linea FOR UPDATE;
 IF l.estado='VALIDADA' THEN RETURN jsonb_build_object('ok',true,'duplicado',true); END IF;
 IF p.estado<>'PENDIENTE' OR l.estado<>'REGISTRADA' THEN RAISE EXCEPTION 'Línea no apta'; END IF;
 PERFORM 1 FROM public.sgp_picking_entregas WHERE id_entrega=l.id_entrega AND estado='VALIDADA' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Entrega Picking sin validación inequívoca'; END IF;
 UPDATE public.sgp_pdt_entrega_lineas SET estado='VALIDADA',validado_por=u,validado_en=now() WHERE id_linea=p_linea;
 RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_asignar_v2(p_token text, p_linea uuid, p_clave uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE l public.sgp_pdt_entrega_lineas%rowtype; parent uuid; e public.sgp_pdt_asignaciones%rowtype; u text; p public.sgp_aluminio_pendientes%rowtype;
BEGIN
 u:=public.sgp_validar_sesion_rol(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','RECEPCION','SUPERVISOR DE PICKING']);
 IF p_clave IS NULL THEN RAISE EXCEPTION 'Clave requerida'; END IF;
 SELECT d.id_pendiente INTO STRICT parent FROM public.sgp_pdt_entrega_lineas x JOIN public.sgp_aluminio_pendiente_detalles d USING(id_detalle) WHERE x.id_linea=p_linea;
 SELECT * INTO STRICT p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=parent FOR UPDATE;
 SELECT * INTO e FROM public.sgp_pdt_asignaciones WHERE clave=p_clave;
 IF FOUND THEN
  IF e.id_linea<>p_linea THEN RAISE EXCEPTION 'Clave reutilizada'; END IF;
  RETURN jsonb_build_object('ok',true,'duplicado',true);
 END IF;
 SELECT * INTO STRICT l FROM public.sgp_pdt_entrega_lineas WHERE id_linea=p_linea FOR UPDATE;
 IF p.estado<>'PENDIENTE' OR l.estado<>'VALIDADA' THEN RAISE EXCEPTION 'Evidencia no apta'; END IF;
 -- Minimal contract: whole line assigned once, to its verified detail only.
 IF (SELECT coalesce(sum(a.cantidad),0) FROM public.sgp_pdt_asignaciones a
 JOIN public.sgp_pdt_entrega_lineas x USING(id_linea) WHERE a.id_detalle=l.id_detalle AND x.estado='VALIDADA')+l.cantidad
 >(SELECT cantidad_validada FROM public.sgp_aluminio_pendiente_detalles WHERE id_detalle=l.id_detalle)
 THEN RAISE EXCEPTION 'Sobreasignación'; END IF;
 INSERT INTO public.sgp_pdt_asignaciones(id_linea,id_detalle,cantidad,clave,asignado_por) VALUES(p_linea,l.id_detalle,l.cantidad,p_clave,u);
 RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_entrega_anular_v2(p_token text, p_linea uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE parent uuid; p public.sgp_aluminio_pendientes%rowtype; l public.sgp_pdt_entrega_lineas%rowtype; u text;
BEGIN
 u:=public.sgp_validar_sesion_rol(p_token,ARRAY['ADMINISTRADOR','COORDINADOR']);
 IF nullif(btrim(p_motivo),'') IS NULL THEN RAISE EXCEPTION 'Motivo requerido'; END IF;
 SELECT d.id_pendiente INTO STRICT parent FROM public.sgp_pdt_entrega_lineas x JOIN public.sgp_aluminio_pendiente_detalles d USING(id_detalle) WHERE x.id_linea=p_linea;
 SELECT * INTO STRICT p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=parent FOR UPDATE;
 SELECT * INTO STRICT l FROM public.sgp_pdt_entrega_lineas WHERE id_linea=p_linea FOR UPDATE;
 IF l.estado='ANULADA' THEN RETURN jsonb_build_object('ok',true,'duplicado',true); END IF;
 IF p.estado<>'PENDIENTE' THEN RAISE EXCEPTION 'Conciliar cierre antes de anular'; END IF;
 UPDATE public.sgp_pdt_entrega_lineas SET estado='ANULADA',motivo=p_motivo,anulado_por=u,anulado_en=now() WHERE id_linea=p_linea;
 INSERT INTO public.sgp_aluminio_pendientes_historial(id_pendiente,usuario,tipo_evento,observacion,datos_nuevos)
 VALUES(parent,u,'ANULACION_ENTREGA_V2',p_motivo,jsonb_build_object('linea',p_linea));
 RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_linea_maestro_v3(p_perfil text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.sgp_maestro_piezas%rowtype;
BEGIN
 SELECT * INTO STRICT m FROM public.sgp_maestro_piezas WHERE codigo_sap=btrim(p_perfil);
 IF m.activo IS DISTINCT FROM 'SI' OR m.tipo_pieza IS NULL OR m.destino_productivo IS NULL OR m.destino_productivo NOT IN ('PANEL','FRAME')
 OR m.tipo_pieza NOT IN ('PANEL','FRAME','COVER','REFUERZO','MUNTIN')
 OR (m.tipo_pieza IN ('PANEL','FRAME') AND m.tipo_pieza<>m.destino_productivo)
 THEN RAISE EXCEPTION 'PDT_MAESTRO_NO_VERIFICABLE'; END IF;
 RETURN CASE m.destino_productivo WHEN 'PANEL' THEN 'PANELES_2' ELSE 'FRAMES_2' END;
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'PDT_MAESTRO_NO_VERIFICABLE';
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_contexto_internal_v3(p_reserva text, p_perfil text, p_produccion text, p_acabado text, p_id_pieza text, p_expected_key text, p_principal text, p_longitud numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE line text; sources jsonb; ctx jsonb; keys_count integer;
BEGIN
 line:=public.sgp_pdt_linea_maestro_v3(p_perfil);
 SELECT jsonb_agg(DISTINCT x),count(DISTINCT x->>'key_produccion') INTO sources,keys_count
 FROM public.sgp_pdt_origenes_internal_v3(p_reserva,p_perfil,p_produccion,p_acabado,p_id_pieza) x
 WHERE x->>'codigo_sap'=btrim(p_perfil) AND x->>'id_linea'=line
 AND (p_longitud IS NULL OR (x->>'longitud')::numeric=p_longitud);
 IF keys_count IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'PDT_ASOCIACION_INEXISTENTE_O_AMBIGUA'; END IF;
 -- Principal and finish must also be unambiguous; caller inputs are assertions only.
 IF (SELECT count(DISTINCT coalesce(x->>'reserva_principal',x->>'reserva')) FROM jsonb_array_elements(sources) x)<>1
 OR (SELECT count(DISTINCT x->>'acabado') FROM jsonb_array_elements(sources) x)<>1
 THEN RAISE EXCEPTION 'PDT_RESERVA_ACABADO_AMBIGUOS'; END IF;
 ctx:=sources->0;
 IF nullif(btrim(p_expected_key),'') IS NOT NULL AND p_expected_key<>ctx->>'key_produccion'
 THEN RAISE EXCEPTION 'PDT_CLAVE_NO_CORRESPONDE_A_MAESTRO'; END IF;
 IF nullif(btrim(p_principal),'') IS NOT NULL AND p_principal<>coalesce(ctx->>'reserva_principal',ctx->>'reserva')
 THEN RAISE EXCEPTION 'PDT_PRINCIPAL_INCONSISTENTE'; END IF;
 RETURN ctx;
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_crear_internal_v3(p_token text, p_reserva text, p_produccion text, p_perfil text, p_cantidad numeric, p_longitud numeric, p_origen text, p_causa text, p_observacion text, p_key_produccion text, p_reserva_principal text, p_acabado_pendiente text, p_id_pieza text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor text; ctx jsonb; id uuid;
BEGIN
 actor:=public.sgp_validar_sesion_rol(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','LIDER MECANIZADO','LIDER','LIDER LINEA']);
 IF p_cantidad IS NULL OR p_cantidad<=0 OR p_cantidad<>trunc(p_cantidad) OR p_cantidad>2147483647 THEN RAISE EXCEPTION 'PDT_CANTIDAD_INVALIDA'; END IF;
 ctx:=public.sgp_pdt_contexto_internal_v3(p_reserva,p_perfil,p_produccion,p_acabado_pendiente,p_id_pieza,p_key_produccion,p_reserva_principal,p_longitud);
 INSERT INTO public.sgp_aluminio_pendientes(reserva,reserva_principal,key_produccion,es_reserva_compartida,acabado_pendiente,produccion,perfil,cantidad,longitud,origen,causa,observacion,usuario_reporte,id_pieza,marca,fabricacion)
 VALUES(ctx->>'reserva',coalesce(ctx->>'reserva_principal',ctx->>'reserva'),ctx->>'key_produccion',coalesce((ctx->>'es_reserva_compartida')::boolean,false),ctx->>'acabado',ctx->>'produccion',btrim(p_perfil),p_cantidad,CASE WHEN p_id_pieza IS NOT NULL THEN coalesce(p_longitud,(ctx->>'longitud')::numeric) ELSE p_longitud END,upper(coalesce(p_origen,'PRODUCCION')),p_causa,p_observacion,actor,
  p_id_pieza,CASE WHEN p_id_pieza IS NOT NULL THEN ctx->>'marca' END,CASE WHEN p_id_pieza IS NOT NULL THEN ctx->>'fabricacion' END)
 RETURNING id_pendiente INTO id;
 RETURN id;
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_proteger_identidad_v3()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ctx jsonb;
BEGIN
 IF TG_OP='UPDATE' AND ROW(NEW.key_produccion,NEW.produccion,NEW.reserva,NEW.perfil,NEW.acabado_pendiente,NEW.id_pieza,NEW.longitud,NEW.contrato_pdt)
 IS NOT DISTINCT FROM ROW(OLD.key_produccion,OLD.produccion,OLD.reserva,OLD.perfil,OLD.acabado_pendiente,OLD.id_pieza,OLD.longitud,OLD.contrato_pdt) THEN RETURN NEW; END IF;
 ctx:=public.sgp_pdt_contexto_internal_v3(NEW.reserva,NEW.perfil,NEW.produccion,NEW.acabado_pendiente,NEW.id_pieza,NEW.key_produccion,NEW.reserva_principal,NEW.longitud);
 IF NEW.key_produccion IS DISTINCT FROM ctx->>'key_produccion' THEN RAISE EXCEPTION 'PDT_CLAVE_NO_VERIFICADA'; END IF;
 IF NEW.contrato_pdt='V2' AND ctx->>'tipo_pieza'<>'PANEL' THEN RAISE EXCEPTION 'PDT_V2_REQUIERE_PIEZA_PANEL'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_entrega_registrar_v2(p_token text, p_detalle uuid, p_entrega uuid, p_cantidad integer, p_clave uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE grouped boolean;
BEGIN
 SELECT id_pieza='' INTO grouped FROM public.sgp_aluminio_pendiente_detalles WHERE id_detalle=p_detalle;
 IF grouped THEN
  IF sgp_pdt_multiorigen.es_registro_v4((SELECT id_pendiente FROM public.sgp_aluminio_pendiente_detalles WHERE id_detalle=p_detalle)) THEN
   RETURN sgp_pdt_multiorigen.grouped_nuevo_entrega(p_token,p_detalle,p_entrega,p_cantidad,p_clave);
  END IF;
  RETURN sgp_pdt_multiorigen.grouped_original_entrega(p_token,p_detalle,p_entrega,p_cantidad,p_clave);
 END IF;
 IF sgp_pdt_multiorigen.es_registro_v4((SELECT id_pendiente FROM public.sgp_aluminio_pendiente_detalles WHERE id_detalle=p_detalle)) THEN
  RETURN sgp_pdt_multiorigen.nuevo_sgp_pdt_entrega_registrar_v2(p_token,p_detalle,p_entrega,p_cantidad,p_clave);
 END IF;
 RETURN sgp_pdt_multiorigen.original_sgp_pdt_entrega_registrar_v2(p_token,p_detalle,p_entrega,p_cantidad,p_clave);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_manual_nc_consultar_v1(p_token text, p_referencia text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE matches integer; data jsonb;
BEGIN
 PERFORM public.sgp_pdt_validar_rol_real(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','LIDER LINEA']);
 IF nullif(btrim(p_referencia),'') IS NULL OR length(p_referencia)>120 THEN RAISE EXCEPTION 'PDT_MANUAL_NC_INVALIDA'; END IF;
 SELECT count(DISTINCT n.consecutivo) INTO matches FROM public.sgp_nc_aluminio n WHERE n.consecutivo=btrim(p_referencia) OR n.cod_nc=btrim(p_referencia);
 IF matches>1 THEN RAISE EXCEPTION 'PDT_MANUAL_NC_AMBIGUA'; END IF;
 SELECT jsonb_build_object('consecutivo',n.consecutivo,'numero',n.cod_nc,'estado',n.estado,
   'reserva_solucion',coalesce(to_jsonb(n)->>'reserva_solucion',to_jsonb(n)->>'reserva_de_solucion'),
   'activo',n.activo) INTO data FROM public.sgp_nc_aluminio n
 WHERE n.consecutivo=btrim(p_referencia) OR n.cod_nc=btrim(p_referencia) LIMIT 1;
 RETURN jsonb_build_object('ok',true,'nc',data);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_manual_registrar_v1(p_token text, p_origen text, p_contexto jsonb, p_detalles jsonb, p_observacion text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor text; program record; sources jsonb; row jsonb; src jsonb; ctx jsonb;
 report uuid; pending uuid; detail uuid; result jsonb; ids jsonb:='[]'; quantity numeric;
 nc text; matches integer; reference_total numeric; source_count integer; signature jsonb;
BEGIN
 IF p_origen='PICKING' THEN
  actor:=public.sgp_pdt_validar_rol_real(p_token,ARRAY['ADMINISTRADOR','COORDINADOR']);
 ELSIF p_origen IN ('ENSAMBLE','EMPAQUE') THEN
  actor:=public.sgp_pdt_validar_rol_real(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','LIDER LINEA']);
 ELSE RAISE EXCEPTION 'PDT_MANUAL_ORIGEN_INVALIDO'; END IF;
 IF p_idempotency_key IS NULL OR jsonb_typeof(p_detalles) IS DISTINCT FROM 'array' OR jsonb_array_length(p_detalles) NOT BETWEEN 1 AND 100
 THEN RAISE EXCEPTION 'PDT_MANUAL_SOLICITUD_INVALIDA'; END IF;
 signature:=jsonb_build_object('origen',p_origen,'contexto',p_contexto,'detalles',p_detalles,'observacion',p_observacion);
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_idempotency_key::text,0));
 SELECT r.id_reporte,r.respuesta,r.solicitud INTO report,result,ctx FROM sgp_pdt_manual.reportes r WHERE r.idempotency_key=p_idempotency_key;
 IF FOUND THEN
  IF ctx IS DISTINCT FROM signature OR (SELECT usuario FROM sgp_pdt_manual.reportes WHERE id_reporte=report)<>actor THEN RAISE EXCEPTION 'PDT_MANUAL_CLAVE_REUTILIZADA'; END IF;
  RETURN result||jsonb_build_object('duplicado',true);
 END IF;
 SELECT * INTO STRICT program FROM sgp_pdt_manual.programacion(p_contexto->>'key_produccion',p_contexto->>'reserva');
 IF program.anio IS NULL OR program.semana NOT BETWEEN 1 AND 53 OR program.acabado=''
 OR program.produccion IS DISTINCT FROM p_contexto->>'produccion'
 THEN RAISE EXCEPTION 'PDT_MANUAL_PROGRAMACION_INCOMPLETA'; END IF;
 sources:=public.sgp_pdt_manual_fuentes_v1(p_token,p_contexto->>'key_produccion',p_contexto->>'reserva')->'fuentes';
 INSERT INTO sgp_pdt_manual.reportes(idempotency_key,anio,semana,linea,key_produccion,produccion,reserva,sistema,acabado,origen,usuario,observacion,solicitud)
 VALUES(p_idempotency_key,program.anio,program.semana,program.linea,p_contexto->>'key_produccion',program.produccion,program.reserva,program.sistema,program.acabado,p_origen,actor,nullif(btrim(p_observacion),''),signature)
 RETURNING id_reporte INTO report;
 FOR row IN SELECT value FROM jsonb_array_elements(p_detalles) LOOP
  quantity:=nullif(row->>'cantidad','')::numeric;nc:=nullif(btrim(row->>'nc'),'');
  IF quantity IS NULL OR quantity<>trunc(quantity) OR quantity<1 OR quantity>2147483647 OR length(coalesce(nc,''))>120 OR coalesce(nc,'')~'[[:cntrl:]]'
  THEN RAISE EXCEPTION 'PDT_MANUAL_CANTIDAD_NC_INVALIDA'; END IF;
  SELECT count(*),coalesce(sum(m.cantidad),0) INTO source_count,reference_total FROM (
   SELECT DISTINCT ON (x->>'id_pieza') x->>'id_pieza' id_pieza,(x->>'cantidad_referencia')::numeric cantidad
   FROM jsonb_array_elements(sources) x
   WHERE x->>'codigo_sap'=row->>'perfil' AND lower(btrim(x->>'fabricacion'))=lower(btrim(row->>'fabricacion'))
   AND lower(btrim(coalesce(x->>'marca','')))=lower(btrim(coalesce(row->>'marca','')))
   AND (x->>'longitud')::numeric=(row->>'longitud')::numeric AND upper(btrim(x->>'acabado'))=upper(btrim(row->>'acabado'))
  ) m;
  IF source_count<1 OR quantity>reference_total OR upper(btrim(row->>'acabado'))<>upper(btrim(program.acabado))
  THEN RAISE EXCEPTION 'PDT_MANUAL_FUENTE_O_CANTIDAD_INVALIDA'; END IF;
  IF EXISTS(SELECT 1 FROM sgp_pdt_manual.detalles d WHERE d.id_reporte=report
   AND d.perfil=row->>'perfil' AND lower(btrim(d.fabricacion))=lower(btrim(row->>'fabricacion'))
   AND lower(btrim(coalesce(d.marca,'')))=lower(btrim(coalesce(row->>'marca','')))
   AND d.longitud=(row->>'longitud')::numeric AND upper(btrim(d.acabado))=upper(btrim(row->>'acabado')))
  THEN RAISE EXCEPTION 'PDT_MANUAL_DETALLE_REPETIDO'; END IF;
  ctx:=public.sgp_pdt_contexto_internal_v3(program.reserva,row->>'perfil',program.produccion,row->>'acabado',NULL,p_contexto->>'key_produccion',NULL,(row->>'longitud')::numeric);
  INSERT INTO public.sgp_aluminio_pendientes(reserva,reserva_principal,key_produccion,es_reserva_compartida,acabado_pendiente,produccion,perfil,cantidad,longitud,origen,causa,observacion,usuario_reporte,id_pieza,marca,fabricacion,nc,contrato_pdt)
  VALUES(ctx->>'reserva',ctx->>'reserva_principal',ctx->>'key_produccion',coalesce((ctx->>'es_reserva_compartida')::boolean,false),ctx->>'acabado',ctx->>'produccion',row->>'perfil',quantity,(row->>'longitud')::numeric,p_origen,'REGISTRO_MANUAL',nullif(btrim(row->>'observacion'),''),actor,NULL,row->>'marca',row->>'fabricacion',nc,'V2') RETURNING id_pendiente INTO pending;
  INSERT INTO sgp_pdt_manual.detalles(id_reporte,id_pendiente,perfil,fabricacion,marca,longitud,acabado,cantidad,nc,observacion)
  VALUES(report,pending,row->>'perfil',row->>'fabricacion',row->>'marca',(row->>'longitud')::numeric,row->>'acabado',quantity::integer,nc,nullif(btrim(row->>'observacion'),'')) RETURNING id_detalle INTO detail;
  FOR src IN SELECT value FROM jsonb_array_elements(sources) x WHERE x.value->>'codigo_sap'=row->>'perfil'
   AND lower(btrim(x.value->>'fabricacion'))=lower(btrim(row->>'fabricacion'))
   AND lower(btrim(coalesce(x.value->>'marca','')))=lower(btrim(coalesce(row->>'marca','')))
   AND (x.value->>'longitud')::numeric=(row->>'longitud')::numeric
   AND upper(btrim(x.value->>'acabado'))=upper(btrim(row->>'acabado')) LOOP
   INSERT INTO sgp_pdt_manual.fuentes(id_detalle,id_pieza,snapshot) VALUES(detail,src->>'id_pieza',src) ON CONFLICT DO NOTHING;
  END LOOP;
  IF row ? 'ncs' THEN
   IF jsonb_typeof(row->'ncs') <> 'array' OR jsonb_array_length(row->'ncs')>20 THEN RAISE EXCEPTION 'PDT_MANUAL_NCS_INVALIDAS'; END IF;
   IF (SELECT count(*)<>count(DISTINCT btrim(value #>> '{}')) FROM jsonb_array_elements(row->'ncs') WHERE btrim(value #>> '{}')<>'') THEN RAISE EXCEPTION 'PDT_MANUAL_NCS_DUPLICADAS'; END IF;
  END IF;
  FOR src IN SELECT value FROM jsonb_array_elements(CASE WHEN row ? 'ncs' THEN row->'ncs' ELSE CASE WHEN nc IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(nc) END END) LOOP
   IF jsonb_typeof(src)<>'string' OR length(btrim(src #>> '{}'))>120 OR btrim(src #>> '{}')~'[[:cntrl:]]' THEN RAISE EXCEPTION 'PDT_MANUAL_NC_INVALIDA'; END IF;
   IF btrim(src #>> '{}')='' THEN CONTINUE; END IF;
   SELECT count(DISTINCT n.consecutivo) INTO matches FROM public.sgp_nc_aluminio n WHERE n.consecutivo=btrim(src #>> '{}') OR n.cod_nc=btrim(src #>> '{}');
   IF matches>1 THEN RAISE EXCEPTION 'PDT_MANUAL_NC_AMBIGUA'; END IF;
   IF matches=0 THEN RAISE EXCEPTION 'PDT_MANUAL_NC_NO_ENCONTRADA'; END IF;
   INSERT INTO public.sgp_aluminio_pendiente_ncs(id_pendiente,consecutivo,enlazado_por,snapshot)
   SELECT pending,n.consecutivo,actor,to_jsonb(n) FROM public.sgp_nc_aluminio n WHERE n.consecutivo=btrim(src #>> '{}') OR n.cod_nc=btrim(src #>> '{}') LIMIT 1;
  END LOOP;
  INSERT INTO public.sgp_aluminio_pendientes_historial(id_pendiente,usuario,estado_anterior,estado_nuevo,tipo_evento,datos_nuevos)
  VALUES(pending,actor,NULL,'PENDIENTE','REGISTRO_MANUAL_V1',jsonb_build_object('id_reporte',report,'origen',p_origen,'fuentes',source_count,'cantidad',quantity));
  ids:=ids||jsonb_build_array(pending);
 END LOOP;
 result:=jsonb_build_object('ok',true,'id_reporte',report,'ids_pendientes',ids);
 UPDATE sgp_pdt_manual.reportes SET respuesta=result WHERE id_reporte=report;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_manual_fuentes_validacion_v1(p_token text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE original record; options jsonb;
BEGIN
 PERFORM public.sgp_pdt_validar_rol_real(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','RECEPCION','LIDER LINEA','SUPERVISOR DE PICKING']);
 SELECT md.*,r.key_produccion,r.produccion,r.reserva,r.acabado AS acabado_reporte,p.validacion_estado
 INTO STRICT original FROM sgp_pdt_manual.detalles md JOIN sgp_pdt_manual.reportes r USING(id_reporte)
 JOIN public.sgp_aluminio_pendientes p USING(id_pendiente) WHERE md.id_pendiente=p_id;
 IF original.validacion_estado='VALIDADO' THEN RAISE EXCEPTION 'PDT_MANUAL_YA_VALIDADO'; END IF;
 SELECT coalesce(jsonb_agg(x ORDER BY x->>'fabricacion',x->>'longitud',x->>'id_pieza'),'[]'::jsonb) INTO options
 FROM (SELECT DISTINCT x FROM public.sgp_pdt_origenes_internal_v3(original.reserva,original.perfil,original.produccion,original.acabado_reporte,NULL) x
  WHERE x->>'key_produccion'=original.key_produccion AND x->>'reserva'=original.reserva
  AND x->>'codigo_sap'=original.perfil AND x->>'tipo_pieza'='PANEL' AND x->>'id_linea'='PANELES_2' LIMIT 1001) q;
 IF jsonb_array_length(options)>1000 THEN RAISE EXCEPTION 'PDT_MANUAL_FUENTES_EXCEDEN_LIMITE'; END IF;
 RETURN jsonb_build_object('ok',true,'original',jsonb_build_object('perfil',original.perfil,'fabricacion',original.fabricacion,
  'marca',original.marca,'longitud',original.longitud,'acabado',original.acabado,'cantidad',original.cantidad,
  'observacion',original.observacion,'nc',original.nc),'fuentes',options);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_manual_asignar_v1(p_token text, p_linea uuid, p_clave uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE line sgp_pdt_manual.entregas%rowtype; parent uuid; actor text; parent_state text;
BEGIN
 actor:=public.sgp_pdt_validar_rol_real(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','RECEPCION','SUPERVISOR DE PICKING']);
 IF p_clave IS NULL THEN RAISE EXCEPTION 'PDT_MANUAL_CLAVE_REQUERIDA'; END IF;
 SELECT d.id_pendiente INTO STRICT parent FROM sgp_pdt_manual.entregas l
 JOIN public.sgp_aluminio_pendiente_detalles d USING(id_detalle) WHERE l.id_linea=p_linea;
 SELECT estado INTO parent_state FROM public.sgp_aluminio_pendientes WHERE id_pendiente=parent AND estado='PENDIENTE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PDT_MANUAL_CERRADO'; END IF;
 SELECT * INTO STRICT line FROM sgp_pdt_manual.entregas WHERE id_linea=p_linea FOR UPDATE;
 IF line.asignado_en IS NOT NULL THEN
  IF line.clave_asignacion<>p_clave THEN RAISE EXCEPTION 'PDT_MANUAL_ASIGNACION_EXISTENTE'; END IF;
  RETURN jsonb_build_object('ok',true,'duplicado',true);
 END IF;
 IF line.estado<>'VALIDADA' OR NOT EXISTS(SELECT 1 FROM public.sgp_picking_entregas
  WHERE id_entrega=line.id_entrega AND estado='VALIDADA') THEN RAISE EXCEPTION 'PDT_MANUAL_ENTREGA_NO_ACREDITABLE'; END IF;
 IF line.cantidad+coalesce((SELECT sum(cantidad) FROM sgp_pdt_manual.entregas
  WHERE id_detalle=line.id_detalle AND estado='VALIDADA' AND asignado_en IS NOT NULL),0)
  >(SELECT cantidad_validada FROM public.sgp_aluminio_pendiente_detalles WHERE id_detalle=line.id_detalle)
 THEN RAISE EXCEPTION 'PDT_MANUAL_SOBREASIGNACION'; END IF;
 UPDATE sgp_pdt_manual.entregas SET asignado_por=actor,asignado_en=now(),clave_asignacion=p_clave WHERE id_linea=p_linea;
 INSERT INTO public.sgp_aluminio_pendientes_historial(id_pendiente,usuario,estado_anterior,estado_nuevo,tipo_evento,datos_nuevos)
 VALUES(parent,actor,parent_state,parent_state,'ASIGNACION_ENTREGA_MANUAL_PDT',jsonb_build_object('linea',p_linea,'cantidad',line.cantidad));
 RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_manual_cerrar_v1(p_token text, p_id uuid, p_clave uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p public.sgp_aluminio_pendientes%rowtype; actor text; prior public.sgp_pdt_cierres%rowtype; final_state text;
BEGIN
 actor:=public.sgp_pdt_validar_rol_real(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','PICKING','SUPERVISOR DE PICKING']);
 IF p_clave IS NULL THEN RAISE EXCEPTION 'PDT_MANUAL_CLAVE_REQUERIDA'; END IF;
 SELECT * INTO STRICT p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM sgp_pdt_manual.detalles WHERE id_pendiente=p_id)
 THEN RAISE EXCEPTION 'PDT_MANUAL_INEXISTENTE'; END IF;
 SELECT * INTO prior FROM public.sgp_pdt_cierres WHERE id_pendiente=p_id;
 IF FOUND THEN
  IF prior.clave<>p_clave THEN RAISE EXCEPTION 'PDT_MANUAL_CIERRE_EXISTENTE'; END IF;
  RETURN jsonb_build_object('ok',true,'duplicado',true);
 END IF;
 IF p.contrato_pdt<>'V2' OR p.estado<>'PENDIENTE' OR p.validacion_estado<>'VALIDADO'
 OR p.estado_repo<>'PROCESADO' THEN RAISE EXCEPTION 'PDT_MANUAL_NO_APTO_PARA_CIERRE'; END IF;
 PERFORM 1 FROM public.sgp_picking_entregas e WHERE e.id_entrega IN (
  SELECT l.id_entrega FROM sgp_pdt_manual.entregas l
  JOIN public.sgp_aluminio_pendiente_detalles d USING(id_detalle) WHERE d.id_pendiente=p_id)
 ORDER BY e.id_entrega FOR UPDATE;
 INSERT INTO public.sgp_pdt_cierres(id_pendiente,clave,usuario,evidencia)
 VALUES(p_id,p_clave,actor,(SELECT coalesce(jsonb_agg(to_jsonb(l)),'[]'::jsonb)
  FROM sgp_pdt_manual.entregas l JOIN public.sgp_aluminio_pendiente_detalles d USING(id_detalle)
  WHERE d.id_pendiente=p_id AND l.estado='VALIDADA' AND l.asignado_en IS NOT NULL));
 IF NOT sgp_pdt_manual.cierre_acreditado(p_id) THEN RAISE EXCEPTION 'PDT_MANUAL_COBERTURA_PICKING_INCOMPLETA'; END IF;
 UPDATE public.sgp_aluminio_pendientes SET estado='RESUELTO',estado_repo='PICKING',usuario_cierre=actor,fecha_cierre=now()
 WHERE id_pendiente=p_id RETURNING estado INTO STRICT final_state;
 INSERT INTO public.sgp_aluminio_pendientes_historial(id_pendiente,usuario,estado_anterior,estado_nuevo,tipo_evento,datos_nuevos)
 VALUES(p_id,actor,p.estado,final_state,'CIERRE_MANUAL_PDT',jsonb_build_object('clave',p_clave));
 RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_manual_entrega_registrar_v1(p_token text, p_detalle uuid, p_entrega uuid, p_cantidad integer, p_clave uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d public.sgp_aluminio_pendiente_detalles%rowtype; p public.sgp_aluminio_pendientes%rowtype;
 prior sgp_pdt_manual.entregas%rowtype; actor text; neto bigint; nuevo uuid;
BEGIN
 actor:=public.sgp_pdt_validar_rol_real(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','PICKING','SUPERVISOR DE PICKING']);
 IF p_cantidad IS NULL OR p_cantidad<=0 OR p_clave IS NULL THEN RAISE EXCEPTION 'PDT_MANUAL_CANTIDAD_O_CLAVE_INVALIDA'; END IF;
 SELECT * INTO STRICT d FROM public.sgp_aluminio_pendiente_detalles WHERE id_detalle=p_detalle;
 SELECT * INTO STRICT p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=d.id_pendiente FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM sgp_pdt_manual.detalles WHERE id_pendiente=p.id_pendiente)
 OR NOT EXISTS(SELECT 1 FROM sgp_pdt_manual.fuentes_validadas WHERE id_detalle=p_detalle)
 THEN RAISE EXCEPTION 'PDT_MANUAL_FUENTE_NO_VALIDADA'; END IF;
 SELECT * INTO prior FROM sgp_pdt_manual.entregas WHERE clave=p_clave;
 IF FOUND THEN
  IF prior.id_detalle<>p_detalle OR prior.id_entrega<>p_entrega OR prior.cantidad<>p_cantidad
  THEN RAISE EXCEPTION 'PDT_MANUAL_CLAVE_REUTILIZADA'; END IF;
  RETURN jsonb_build_object('ok',true,'duplicado',true,'id_linea',prior.id_linea);
 END IF;
 IF p.contrato_pdt<>'V2' OR p.estado<>'PENDIENTE' OR p.validacion_estado<>'VALIDADO'
  OR p.estado_repo NOT IN ('MECANIZADO','PROCESADO') OR p.fecha_cierre IS NOT NULL
 THEN RAISE EXCEPTION 'PDT_MANUAL_NO_APTO_PARA_ENTREGA'; END IF;
 PERFORM 1 FROM public.sgp_picking_entregas WHERE id_entrega=p_entrega FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PDT_MANUAL_ENTREGA_INEXISTENTE'; END IF;
 PERFORM 1 FROM public.sgp_mecanizado_programacion mp JOIN public.sgp_picking_entregas pe USING(id_programacion)
  WHERE pe.id_entrega=p_entrega FOR UPDATE OF mp;
 PERFORM 1 FROM public.sgp_picking_entregas pe JOIN public.sgp_mecanizado_programacion mp USING(id_programacion)
 JOIN public.sgp_producciones prod ON prod.key_produccion=p.key_produccion
 WHERE pe.id_entrega=p_entrega AND pe.produccion=prod.produccion
 AND upper(btrim(mp.sistema))=upper(btrim(prod.sistema)) AND upper(btrim(mp.acabado))=upper(btrim(d.acabado))
 AND (mp.reserva=p.reserva OR (mp.reserva=p.reserva_principal AND EXISTS(
  SELECT 1 FROM public.sgp_produccion_reservas_v rel WHERE rel.key_produccion=p.key_produccion
  AND rel.reserva=p.reserva AND rel.reserva_principal=mp.reserva)));
 IF NOT FOUND THEN RAISE EXCEPTION 'PDT_MANUAL_ENTREGA_AJENA'; END IF;
 SELECT coalesce(sum(CASE WHEN tipo='AVANCE' THEN cantidad ELSE -cantidad END),0) INTO neto
 FROM public.sgp_aluminio_pendiente_movimientos WHERE id_detalle=p_detalle;
 IF p_cantidad+coalesce((SELECT sum(cantidad) FROM sgp_pdt_manual.entregas
  WHERE id_detalle=p_detalle AND estado<>'ANULADA'),0)>neto
 THEN RAISE EXCEPTION 'PDT_MANUAL_ENTREGA_SUPERA_PROCESADO'; END IF;
 INSERT INTO sgp_pdt_manual.entregas(id_detalle,id_entrega,cantidad,clave,registrado_por)
 VALUES(p_detalle,p_entrega,p_cantidad,p_clave,actor) RETURNING id_linea INTO nuevo;
 INSERT INTO public.sgp_aluminio_pendientes_historial(id_pendiente,usuario,estado_anterior,estado_nuevo,tipo_evento,datos_nuevos)
 VALUES(p.id_pendiente,actor,p.estado,p.estado,'ENTREGA_MANUAL_PDT',jsonb_build_object('linea',nuevo,'detalle',p_detalle,'entrega',p_entrega,'cantidad',p_cantidad));
 RETURN jsonb_build_object('ok',true,'id_linea',nuevo);
END $function$

