CREATE OR REPLACE FUNCTION public.sgp_pdt_proteger_entrega_origen()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM public.sgp_pdt_entrega_lineas WHERE id_entrega=OLD.id_entrega AND estado<>'ANULADA') THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Entrega con evidencia PDT vigente'; END IF;
  IF ROW(NEW.produccion,NEW.id_programacion) IS DISTINCT FROM ROW(OLD.produccion,OLD.id_programacion) THEN
   RAISE EXCEPTION 'Conciliar evidencia PDT antes de modificar entrega';
  END IF;
  -- Registered quantities do not certify delivery: let the legacy audit produce
  -- VALIDADA or AUDITADA_DIFERENCIA. Once certified, annul explicitly first.
  IF NEW.estado IS DISTINCT FROM OLD.estado AND EXISTS(
   SELECT 1 FROM public.sgp_pdt_entrega_lineas WHERE id_entrega=OLD.id_entrega AND estado='VALIDADA') THEN
   RAISE EXCEPTION 'Conciliar evidencia PDT antes de modificar entrega';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sgp_picking_rechazar_entrega_completa_duplicada()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.completa is distinct from true then
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(new.id_programacion::text || '|' || new.produccion, 0));
  if exists (
    select 1 from public.sgp_picking_entregas e
    where e.id_programacion = new.id_programacion
      and e.produccion = new.produccion
      and e.completa is true
      and e.estado in ('PENDIENTE_VALIDACION','VALIDADA','AUDITADA_DIFERENCIA')
  ) then
    raise exception 'ENTREGA_COMPLETA_YA_REGISTRADA: la producción ya tiene una entrega completa activa'
      using errcode = '23505';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sgp_picking_validar_jornada_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz := statement_timestamp();
  v_local timestamp := v_now AT TIME ZONE 'America/Bogota';
  v_date date := v_local::date;
  v_hour time := v_local::time;
  v_prev date := v_date - 1;
  v_prev_sunday boolean := extract(isodow from v_prev) = 7;
  v_expected_date date;
  v_expected_turn text;
  v_start timestamptz;
  v_start_hour integer;
BEGIN
  IF v_hour >= time '07:00' THEN
    v_expected_date := v_date;
    IF extract(isodow from v_date) = 7 THEN
      v_expected_turn := CASE WHEN v_hour < time '18:00' THEN 'TURNO 1' ELSE 'TURNO 2' END;
    ELSE
      v_expected_turn := CASE WHEN v_hour < time '19:00' THEN 'TURNO 1' ELSE 'TURNO 2' END;
    END IF;
  ELSIF v_prev_sunday AND v_hour >= time '05:00' THEN
    v_expected_date := NULL; -- No active shift Monday 05:00-07:00.
  ELSE
    v_expected_date := v_prev;
    v_expected_turn := 'TURNO 2';
  END IF;

  -- Legacy 6-argument RPC omits both fields. Fill both from the actual active shift.
  IF NEW.fecha_operativa IS NULL AND NEW.turno_entrega IS NULL THEN
    IF v_expected_date IS NULL THEN
      RAISE EXCEPTION 'PICKING_SIN_TURNO_ACTIVO';
    END IF;
    NEW.fecha_operativa := v_expected_date;
    NEW.turno_entrega := v_expected_turn;
  ELSIF NEW.fecha_operativa IS NULL OR NEW.turno_entrega IS NULL THEN
    RAISE EXCEPTION 'PICKING_FECHA_TURNO_REQUERIDOS';
  END IF;

  NEW.turno_entrega := upper(btrim(NEW.turno_entrega));
  IF NEW.turno_entrega NOT IN ('TURNO 1','TURNO 2') THEN
    RAISE EXCEPTION 'PICKING_TURNO_INVALIDO';
  END IF;
  v_start_hour := CASE
    WHEN NEW.turno_entrega = 'TURNO 1' THEN 7
    WHEN extract(isodow from NEW.fecha_operativa) = 7 THEN 18
    ELSE 19
  END;
  v_start := (NEW.fecha_operativa::timestamp + make_interval(hours => v_start_hour))
    AT TIME ZONE 'America/Bogota';
  IF v_start > v_now THEN
    RAISE EXCEPTION 'PICKING_TURNO_FUTURO';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION sgp_pdt_manual.auditar_programacion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE before_week integer; after_week integer; current_year integer; item record; inserted uuid;
BEGIN
 before_week:=coalesce(OLD.semana_actual,OLD.semana_base);
 -- Deferred execution observes the final row after Export updates week and year.
 SELECT p.anio,coalesce(p.semana_actual,p.semana_base) INTO STRICT current_year,after_week
 FROM public.sgp_producciones p WHERE p.key_produccion=NEW.key_produccion;
 IF ROW(OLD.anio,before_week) IS NOT DISTINCT FROM ROW(current_year,after_week) THEN RETURN NEW; END IF;
 IF OLD.anio NOT BETWEEN 2020 AND 2100 OR current_year NOT BETWEEN 2020 AND 2100
 OR before_week NOT BETWEEN 1 AND 53 OR after_week NOT BETWEEN 1 AND 53
 THEN RAISE EXCEPTION 'PDT_MANUAL_PERIODO_INVALIDO'; END IF;
 FOR item IN SELECT DISTINCT md.id_pendiente FROM sgp_pdt_manual.reportes r
  JOIN sgp_pdt_manual.detalles md USING(id_reporte)
  WHERE r.key_produccion=NEW.key_produccion LOOP
  inserted:=NULL;
  INSERT INTO sgp_pdt_manual.programacion_cambios
   (id_pendiente,key_produccion,anio_anterior,semana_anterior,anio_nuevo,semana_nueva)
  VALUES(item.id_pendiente,NEW.key_produccion,OLD.anio,before_week,current_year,after_week)
  ON CONFLICT(id_pendiente,transaccion) DO NOTHING RETURNING id_cambio INTO inserted;
  IF inserted IS NULL THEN CONTINUE; END IF;
  INSERT INTO public.sgp_aluminio_pendientes_historial
   (id_pendiente,usuario,tipo_evento,observacion,estado_anterior,estado_nuevo,datos_anteriores,datos_nuevos)
  VALUES(item.id_pendiente,current_user,'REPROGRAMACION_PDT_MANUAL',
   'Cambio de programación; el reporte original permanece inmutable',
   (SELECT estado_repo FROM public.sgp_aluminio_pendientes WHERE id_pendiente=item.id_pendiente),
   (SELECT estado_repo FROM public.sgp_aluminio_pendientes WHERE id_pendiente=item.id_pendiente),
   jsonb_build_object('anio',OLD.anio,'semana',before_week,'key_produccion',OLD.key_produccion),
   jsonb_build_object('anio',current_year,'semana',after_week,'key_produccion',NEW.key_produccion));
 END LOOP;
 RETURN NEW;
END $function$
